(window.YSKAR_TEXTE=window.YSKAR_TEXTE||{}).fr={"nav.skip":"Aller au contenu","nav.main":"Navigation principale","nav.menu":"Menu","nav.close":"Fermer","nav.lang":"Langue","nav.tick":"Bloc","nav.tick.title":"Le bloc le plus récent. Ouvre la page du réseau en direct.","cta.join":"Participer","nav.g.part":"Participer","nav.g.know":"Comprendre","nav.g.join":"En faire partie","nav.start":"Par où commencer","nav.start.d":"Cinq portes d’entrée, chacune avec son premier pas","nav.mine":"Miner","nav.mine.d":"Trouve des blocs avec un téléphone, un PC ou une carte graphique","nav.wallet":"Portefeuille","nav.wallet.d":"Douze mots que toi seul détiens","nav.node":"Faire tourner un nœud","nav.node.d":"Vérifie chaque bloc toi-même","nav.ysr":"YSR","nav.ysr.d":"21 millions, tous minés un par un","nav.chain":"La chaîne","nav.chain.d":"Une blockchain à part entière, et comment elle fait ses preuves","nav.network":"Le réseau, en direct","nav.network.d":"Ce que fait la chaîne en ce moment","nav.explorer":"Explorateur","nav.explorer.d":"Chaque bloc, chaque transfert, chaque adresse","nav.community":"Communauté","nav.community.d":"Là où le projet discute et décide","nav.build":"Développer","nav.build.d":"Code ouvert, API publique, propositions","nav.story":"Histoire et prochaines étapes","nav.story.d":"Du bloc 0 à aujourd’hui, et ce qui vient ensuite","foot.claim":"Équitable dès le bloc 0.","foot.sub":"YSKAR est un projet communautaire. Aucune entreprise n’est derrière, et il n’y a personne à croire sur parole : chaque bloc peut être vérifié.","foot.nav":"Toutes les pages","foot.whitepaper":"Livre blanc","foot.find":"Trouver YSKAR","foot.imprint":"Mentions légales","foot.privacy":"Confidentialité","foot.license":"Open source sous licence MIT","title.home":"Équitable dès le bloc 0","title.start":"Par où commencer","title.mine":"Minage","title.wallet":"YSKAR Wallet","title.node":"Faire tourner un nœud","title.ysr":"YSR, la pièce","title.chain":"La chaîne","title.network":"Le réseau, en direct","title.explorer":"Explorateur","title.build":"Développer sur YSKAR","title.community":"Communauté","title.story":"Histoire et prochaines étapes","ui.copied":"Copié","ui.copy":"Copier","ui.sample":"L’écran affiche des données d’exemple.","dawn.h":"Ici, il est encore tôt.","dawn.p":"Jour <span data-live='day'></span>. La première lueur se lève à peine sur ce réseau. Ceux qui le façonnent sont ceux qui sont là maintenant.","dawn.cta2":"Lire l’histoire jusqu’ici","dawn.alt":"Le même fjord aux premières lueurs : un ciel pâle au-dessus de montagnes enneigées et d’une eau calme.","nav.guides":"Guides","nav.guides.d":"Toutes les façons de participer, pas à pas","nav.protocol":"Protocole","nav.protocol.d":"Pièce, chaîne et portefeuilles, octet par octet","nav.paper.d":"Le système tel qu’il est implémenté","title.guides":"Guides","title.protocol":"Protocole","title.paper":"Livre blanc","title.imprint":"Mentions légales","title.privacy":"Confidentialité","doc.toc":"Sur cette page","foot.live":"Les chiffres de ces pages sont lus en direct depuis l’API publique de YSKAR.","foot.stale":"L’API publique de YSKAR ne répond pas pour le moment. Ces pages montrent la chaîne telle qu’elle était le {date} (bloc {h}) et se remettent à jour d’elles-mêmes.","title.notfound":"Page introuvable","nf.h":"Cette page n’existe pas.","nf.p":"Le lien est peut-être mal saisi, ou la page a été déplacée. La chaîne, elle, est exactement là où elle était.","nf.home":"Vers la page d’accueil","nf.explorer":"Chercher quelque chose dans l’explorateur","home.hero.h1":"<span class=\"ln\"><span>Proof,</span></span> <span class=\"ln\"><span>not promise.</span></span>","home.hero.lead":"YSKAR est une monnaie dotée de sa propre blockchain. Rien n’a été distribué à l’avance : chaque YSR est miné, et chacun peut vérifier chaque bloc. Équitable dès le bloc 0.","home.hero.cta2":"Voir la chaîne jusqu’ici","home.hero.live":"Jour {d} · bloc {h} · {n} lumières sur la rive, une pour chaque nœud qui s’est signalé","home.hero.alt":"Un fjord sombre entre des montagnes enneigées sous un ciel étoilé. Des rubans de lumière bleue ondulent au-dessus, et de petites lumières chaudes brillent sur la rive opposée.","home.m1":"Tout n’a pas commencé par une promesse. Tout a commencé par un bloc.","home.m2":"Rien n’a été miné à l’avance. Rien n’a été distribué. Environ 1,07 million de YSR des premiers jours ont été brûlés pour compenser l’avance prise au départ.","home.m3":"Depuis, un nouveau YSR ne vient au monde que d’une seule façon : une machine fait le travail, et chacun peut le vérifier.","walk.start.h":"<span data-live='day'></span> jours, bloc après bloc.","walk.start.p":"Chaque lumière est un vrai bloc, et l’écart entre deux lumières est le temps qui les sépare. Fais défiler pour parcourir la chaîne. Touche une lumière pour ouvrir son bloc.","walk.c0.h":"Tout commence par un bloc.","walk.c0.p":"Son seul message est « proof, not promise ». Sa récompense de 875 YSR est allée à une adresse dont personne ne peut rien dépenser.","walk.c1.h":"Premier jour : 46 blocs.","walk.c1.p":"Le premier bloc après le bloc 0 est arrivé à 18:03 UTC. À minuit, il y en avait 46 : la chaîne avait trouvé son rythme.","walk.c3.h":"L’avance du départ est brûlée.","walk.c3.p":"1 066 101 YSR des premiers jours sont envoyés à l’adresse dont personne ne peut rien dépenser, pour compenser l’avance prise au départ. Tout est dans ce bloc.","walk.c4.h":"La communauté vote.","walk.c4.p":"La révision 6 se décide au grand jour : comptes partagés, verrous temporels, paiements à mille destinataires à la fois. Trois mises à jour des règles étaient déjà en vigueur à ce moment-là.","walk.c5.h":"Tu es ici.","walk.c5.p":"Le prochain bloc est à une dizaine de minutes.","walk.c6.h":"Ensuite : la révision 6 s’active.","walk.c6.p":"Dans <span data-live='v6Left'></span> blocs. Chaque nœud connaît la hauteur à l’avance, donc rien ne change par surprise.","walk.c6.h.past":"La révision 6 est active.","walk.c6.p.past":"Depuis le bloc 10 000, la chaîne connaît les comptes partagés, les verrous temporels et les paiements groupés.","walk.c7.h":"Puis la première époque s’achève.","walk.c7.p":"Jusqu’au bloc 12 000, chaque bloc crée 875 YSR, puis 437,5. La moitié de tous les YSR qui existeront jamais vient de cette première époque.","walk.c7.h.past":"La première époque est terminée.","walk.c7.p.past":"Depuis le bloc 12 000, chaque bloc crée 437,5 YSR. La récompense est de nouveau divisée par deux tous les 12 000 blocs.","walk.open":"Ouvrir ce bloc","walk.k.block":"Bloc {h} · {d}","walk.k.future":"Bloc {h} · encore à venir","home.walk.now":"Bloc {h} · jour {d}","walk.hud.block":"Bloc {h}","walk.hud.ahead":"Bloc {h}","walk.hud.planned":"encore à venir · fixé dans le code","walk.hud.day":"jour {n}","walk.tip.block":"Bloc {h}","walk.tip.approx":"Les détails se chargent dans l’explorateur","walk.tip.solo":"Trouvé par un mineur seul","walk.tip.pool":"Trouvé par un pool","walk.tip.tx":"contenait des transferts","walk.legend.block":"un bloc","walk.legend.tx":"un bloc qui contenait des transferts","walk.canvas":"La chaîne dessinée comme un ruban de lumières, une lumière pour chaque bloc depuis le bloc 0.","home.proof.h":"Ne nous crois pas sur parole.","home.proof.p":"Chaque bloc porte sa propre preuve. Ton appareil peut la vérifier tout de suite : pas de serveur, pas de compte, seulement de l’arithmétique.","prove.btn.genesis":"Vérifier le bloc 0 sur cet appareil","prove.btn.tip":"Vérifier le bloc le plus récent","prove.label":"Hash de l’en-tête du bloc","prove.ok":"Valide. Le bloc {h} a été vérifié sur cet appareil en {ms} ms.","prove.bad":"Non valide : le bloc {h} manque sa cible.","prove.open":"Ouvrir le bloc {h} dans l’explorateur","prove.note":"Ce que ton appareil vient de faire : il a passé les 136 octets de l’en-tête du bloc deux fois dans SHA-256. Le résultat doit être plus petit que la cible fixée par le réseau pour ce bloc. Les zéros du début montrent à quel point il est petit.","home.ways.h":"Trois portes d’entrée.","home.ways.p":"L’emblème de YSKAR, ce sont trois rubans qui se rejoignent. Le réseau aussi : des gens qui minent, des gens qui détiennent et envoient, et des gens qui font tourner un nœud.","way.mine.h":"Prête-lui ta machine.","way.mine.p":"Un téléphone, un PC ou une carte graphique peuvent trouver des blocs. Seul, ou dans un pool qui te paie dans le bloc lui-même et ne détient jamais tes pièces.","way.mine.cta":"Comment fonctionne le minage","way.mine.alt":"Un ordinateur portable sur un bureau en bois, la nuit, sur lequel tourne YSKAR Node Core ; derrière, une fenêtre donnant sur un fjord sombre.","way.wallet.h":"Douze mots. Rien qu’à toi.","way.wallet.p":"Ton portefeuille se trouve sur ton propre appareil. Personne d’autre ne détient tes clés, pas même ceux qui développent YSKAR.","way.wallet.cta":"Obtenir le portefeuille","way.wallet.alt":"Un téléphone avec YSKAR Wallet ouvert, posé sur un bureau en bois sombre à côté d’un carnet portant douze lignes manuscrites, d’un stylo et d’une tasse de thé.","way.node.h":"Laisse une lumière allumée.","way.node.p":"Un nœud vérifie lui-même chaque bloc, depuis le bloc 0. Chacun rend le réseau plus difficile à faire plier. Un petit ordinateur sur un rebord de fenêtre suffit.","way.node.cta":"Faire tourner un nœud","way.node.alt":"Un petit ordinateur avec un voyant cyan sur un rebord de fenêtre en bois ; dehors, un fjord la nuit et quelques lumières sur la rive opposée.","home.ways.more":"Ou construis dessus. Le code est ouvert, l’API est publique, et les propositions se discutent là où tout le monde peut les lire.","home.ways.more.cta":"Pour les développeurs","home.early.say":"Jour {d}. {n} nœuds. {m} mineurs. {p} pools. {x} transferts. Pas de cotation. Pas de prix. Voilà à quoi ressemble un début.","home.early.note":"Nœuds et mineurs tels qu’ils se signalent eux-mêmes. Tous les chiffres viennent de l’API publique.","home.early.p":"Un petit réseau, âgé de <span data-live='day'></span> jours. YSR n’est coté nulle part et n’a pas de prix ; des cotations sont en préparation, sans date et sans noms. Ce qui existe aujourd’hui : une chaîne qui fonctionne, des logiciels que tu peux faire tourner, et de la place pour ceux qui arrivent maintenant.","home.era.h":"Époque <span data-live='era'></span>","home.era.p":"Dans cette époque, chaque bloc crée <span data-live='rewardNow'></span> YSR. Au bloc <span data-live='halvingHeight'></span>, la récompense est divisée par deux, puis de nouveau tous les 12 000 blocs. La moitié de tous les YSR qui existeront jamais vient des 12 000 premiers blocs. Le calendrier est écrit dans le code ; personne ne peut le déplacer.","home.era.now":"Bloc <span data-live='height'></span>","home.era.left":"Encore <span data-live='halvingLeft'></span> blocs","home.era.cta":"Le calendrier complet","home.people.h":"Pas d’entreprise. Juste des gens.","home.people.p":"YSKAR est un projet communautaire et appartient à ceux qui l’utilisent. Ils minent, font tourner des nœuds, testent les versions et décident des changements au grand jour : la révision 6 a été soumise à un vote de la communauté.","home.people.cta":"Rencontrer la communauté","home.people.cta2":"Ouvrir YSKAR Lab","home.people.alt":"Une quinzaine de personnes vues de dos sur une rive enneigée à l’heure bleue, chacune tenant une petite lanterne, le regard tourné vers un fjord.","start.h1":"Choisis ta porte d’entrée.","start.lead":"Participer ne coûte rien. Commence par ce qui te convient ; les mêmes douze mots ouvriront toutes les portes ensuite.","start.1.h":"Je veux détenir et envoyer des YSR","start.1.p":"Installe le portefeuille Android, écris douze mots sur papier, montre ton adresse. Il n’en faut pas plus pour recevoir.","start.1.do":"Vers le portefeuille","start.2.h":"Je veux miner","start.2.p":"Commence avec l’appareil que tu as déjà : Node Core sur un PC, l’app Android sur un téléphone, la ligne de commande sur un rig.","start.2.do":"Vers le minage","start.3.h":"Je veux vérifier la chaîne moi-même","start.3.p":"Fais tourner un nœud. Il vérifie chaque bloc depuis le bloc 0 et devient une lumière de plus sur la rive.","start.3.do":"Faire tourner un nœud","start.4.h":"Je veux développer ou aider","start.4.p":"Lis le code, interroge l’API publique, teste une version, apporte une proposition au YSKAR Lab.","start.4.do":"Pour les développeurs","start.5.h":"Pour l’instant, je veux juste regarder","start.5.p":"Suis la chaîne en direct, ouvre n’importe quel bloc dans l’explorateur, lis ce qui se dit sur le canal.","start.5.do":"Le réseau, en direct","start.safe.h":"Trois choses à savoir d’abord","start.alt.fjord":"Un fjord sombre sous un ciel étoilé.","mine.h1":"Prête-lui ta machine.","mine.lead":"Les nouveaux YSR viennent du minage et de nulle part ailleurs. Un téléphone, un PC ou une carte graphique peuvent participer, seuls ou dans un pool.","mine.cta":"Choisis ta configuration","mine.cta2":"Essaie ici même","mine.try.h":"Miner, c’est deviner, très vite.","mine.try.p":"Appuie sur démarrer et cet appareil participe un instant. Il prend le bloc le plus récent et cherche un nombre qui fait commencer son hash par assez de zéros : la même recherche que mène chaque mineur, avec une difficulté d’entraînement.","mine.try.go":"Commencer à deviner","mine.try.stop":"Arrêter","mine.try.again":"Encore une fois","mine.try.tries":"Essais","mine.try.speed":"Vitesse","mine.try.idle":"Rien trouvé pour l’instant. Chaque étincelle est une série d’essais.","mine.try.found":"Trouvé après {n} essais.","mine.try.none":"Pas de chance en {n} essais. Ça aussi, c’est miner. Réessaie.","mine.try.real":"C’était un entraînement. Le vrai réseau est plus difficile d’un facteur de {x} : à {r}, cet appareil seul aurait besoin d’environ {t} pour un vrai bloc. C’est pour cela que les mineurs rejoignent des pools.","mine.try.canvas":"Des étincelles pour chaque série d’essais ; un éclair vif quand un nombre valide est trouvé.","mine.setup.h":"Choisis ta configuration","mine.calc.h":"Que pourrait trouver ta machine ?","mine.pools.h":"Les pools, en direct","wal.h1":"Douze mots. Rien qu’à toi.","wal.lead":"YSKAR Wallet est l’app Android pour YSR : envoyer, recevoir, signer. Ta clé est créée sur ton téléphone et y reste.","wal.cta2":"Installer en quatre étapes","wal.say":"Celui qui a les douze mots a les fonds. Écris-les sur papier. Personne chez YSKAR ne te les demandera jamais.","node.h1":"Laisse une lumière allumée.","node.lead":"Un nœud complet vérifie lui-même chaque bloc, depuis le bloc 0, et le transmet. Il ne demande à personne ce qui est vrai. Chaque nœud qui fait cela rend le réseau plus difficile à faire plier.","node.cta":"Obtenir Node Core","node.cta2":"En ligne de commande","node.say":"Chaque lumière sur cette rive est un nœud qui s’est signalé. Il y en a {n} en ce moment. Le tien serait le numéro {k}.","node.core.h":"Node Core : nœud, portefeuille et mineur dans une seule fenêtre.","node.core.p":"Installe-le, et ton ordinateur vérifie la chaîne par lui-même. Node Core contient aussi ton portefeuille, mine avec ton processeur ou ta carte graphique, peut faire tourner un pool et signe des messages. Version 1.1.0 pour Windows 10 et 11 et pour Linux 64 bits.","node.dl.win":"Installateur Windows","node.dl.deb":"Paquet Linux (.deb)","node.dl.app":"AppImage Linux","node.dl.get":"Télécharger","node.dl.all":"Tous les fichiers et sommes de contrôle","node.dl.rel":"La version sur GitHub","node.why.h":"Ce que change un nœud de plus","node.w1.p":"Ton nœud recalcule le travail, les signatures et chaque solde, à partir du bloc 0. Un bloc qui enfreint une règle est rejeté, quel que soit son expéditeur.","node.w2.h":"Il porte le réseau","node.w2.p":"Chaque nœud transmet les blocs et les transferts aux autres. Plus ils sont nombreux, en des lieux différents, moins le réseau dépend d’une seule machine.","node.w3.h":"Il lui faut peu","node.w3.p":"En ligne de commande, un nœud tourne sous Linux, Windows et macOS, même sur un Raspberry Pi. Node Core, l’app de bureau, tourne sous Windows et sous Linux 64 bits.","coin.h1":"21 millions. Tous minés, un par un.","coin.lead":"YSR est la pièce de la chaîne YSKAR. Il n’y en aura jamais plus de 21 000 000. Rien n’a été préminé ni attribué : un nouveau YSR n’existe que pour une seule raison, un bloc a été trouvé.","coin.alt":"La pièce YSR : un disque épais de verre bleu au bord relevé, avec l’emblème de YSKAR en relief.","coin.alt.flat":"La pièce YSR : un disque sombre avec un anneau bleu et l’emblème de YSKAR.","coin.bar.mined":"minés jusqu’ici","coin.bar.burned":"dont brûlés ou impossibles à dépenser","coin.bar.open":"encore à miner","coin.eras.h":"La récompense est divisée par deux tous les 12 000 blocs.","coin.eras.p":"Chaque barre est une époque et montre combien de YSR elle crée. La première époque crée à elle seule la moitié du total. Le dernier nouveau YSR apparaît au bloc 443 999 ; ensuite, les mineurs ne touchent plus que les frais.","coin.eras.era":"Époque {n}","coin.eras.now":"actuelle","coin.eras.rest":"Chiffres en YSR. 9+ regroupe toutes les époques suivantes.","coin.burn.h":"L’avance du départ a été brûlée.","coin.burn.cta":"Le voir dans le bloc 3 974","chain.h1":"Une chaîne à part entière.","chain.lead":"YSKAR ne repose sur aucun autre réseau. Il a ses propres blocs, son propre réseau pair à pair et ses propres règles, et il prouve chaque bloc par un travail que chacun peut vérifier.","chain.how.h":"Un bloc, trois étapes.","chain.why.h":"Pourquoi avoir sa propre chaîne compte","chain.y1.h":"Ses règles lui appartiennent","chain.y1.p":"Les frais, les temps de bloc et les mises à jour se décident ici, par ceux qui font tourner YSKAR, et non sur le réseau de quelqu’un d’autre.","chain.y2.h":"Rien à croire sur parole","chain.y2.p":"Chaque bloc, jusqu’au bloc 0, peut être recalculé par n’importe qui, avec un logiciel ouvert, sur un ordinateur ordinaire.","chain.y3.h":"Les changements arrivent au grand jour","chain.y3.p":"Un changement de règle est écrit dans le code avec le bloc auquel il commence. Chaque nœud le connaît à l’avance. La révision 6 a été soumise à un vote de la communauté.","chain.deep.h":"Pour les curieux : le fonctionnement en détail","chain.deep.p":"À partir d’ici, la page devient technique. Tout ce qui suit vient du code de consensus et de la chaîne elle-même.","netp.lead":"Ce que fait la chaîne en ce moment, lu depuis l’API publique. Rien ici n’est estimé à la main.","bld.h1":"Construis dessus.","bld.lead":"Tout YSKAR est ouvert : nœud, portefeuilles, mineurs, explorateur et ce site, sous licence MIT. Une API publique répond sans clé.","bld.cta":"Essayer l’API","bld.cta2":"Le code sur GitHub","bld.1.h":"Tout lire","bld.1.p":"Le protocole est spécifié, le code de consensus est assez court pour être lu, et chaque chiffre de ce site vient de ce code ou de la chaîne.","bld.2.h":"Interroger la chaîne","bld.2.p":"Blocs, transferts, adresses, frais, pools et offre en simple HTTP. Pas de clé, pas d’inscription, ouverte à n’importe quel site.","bld.3.h":"Le changer","bld.3.p":"Les propositions passent par le YSKAR Lab, en public, de la première idée à la version publiée. Tu te connectes avec ton portefeuille.","comm.h1":"Pas d’entreprise. Juste des gens.","comm.lead":"YSKAR est un projet communautaire et appartient à ceux qui l’utilisent. C’est ici qu’ils discutent, testent et décident.","comm.ch.h":"Où trouver tout le monde","comm.do.h":"Ce que tu peux faire. Rien de tout cela ne demande de permission.","comm.lab.h":"Comment une proposition devient une version","comm.safe.h":"Reste en sécurité","comm.ann":"Bitcointalk","story.h1":"Des étapes, pas des dates.","story.lead":"D’où vient YSKAR, ce qui fonctionne aujourd’hui et ce qui vient ensuite. Personne ici ne promet de date de livraison : les changements prennent effet à un bloc, pas à un jour du calendrier.","story.why.h":"Pourquoi YSKAR existe","story.why.say":"Le but est une monnaie que les gens peuvent utiliser au quotidien. Des fondations solides passent d’abord. Un bref emballement n’est pas le plan.","story.why.p":"YSKAR appartient à ceux qui l’utilisent. Tes YSR se trouvent à une adresse que seuls tes douze mots ouvrent. Il n’y a personne à qui faire confiance : chaque bloc, jusqu’au bloc 0, peut être vérifié par n’importe qui. Les nouveaux YSR viennent du minage, jamais d’une promesse.","story.run.h":"En service aujourd’hui","story.fix.h":"Fixé par hauteur de bloc","story.plan.h":"Prévu, sans date","story.walk":"Parcourir la chaîne depuis le bloc 0","coin.field.alt":"Un champ de lumières pour les 21 millions de YSR : ceux déjà minés sont allumés, ceux qui ont été brûlés rougeoient comme des braises, le reste est sombre.","coin.field.burned":"brûlés","coin.f0.h":"21 000 000. Jamais plus.","coin.f0.p":"Chaque lumière représente <span data-field-unit></span> YSR, dans l’ordre où ils voient le jour. C’est tout ce qui existera jamais.","coin.f1.p":"Voilà ce qui existe aujourd’hui, soit <span data-live='mintedPct'></span> du total. Chacun d’eux est sorti d’un bloc que quelqu’un a trouvé.","coin.f2.p":"Environ 1,07 million de YSR des premiers jours ont été brûlés pour compenser l’avance prise au départ. Ils sont allés à une adresse dont personne ne peut rien dépenser et ont disparu pour de bon.","coin.f3.h":"La moitié de tout arrive en premier.","coin.f3.p":"Les 12 000 premiers blocs créent 10,5 millions de YSR : la moitié de tout ce qui existera jamais. La chaîne en est au bloc <span data-live='height'></span>.","coin.f4.h":"Puis la récompense est divisée par deux, encore et encore.","coin.f4.p":"Tous les 12 000 blocs, la récompense est divisée par deux. Le dernier nouveau YSR apparaît au bloc 443 999. Ensuite, les mineurs ne touchent plus que les frais.","coin.noprice.say":"YSR n’a pas de prix aujourd’hui. Il n’est coté nulle part. Ce qu’il a, c’est une chaîne que chacun peut vérifier.","wal.phone.alt":"Un téléphone affichant de vrais écrans de YSKAR Wallet, l’un après l’autre.","wal.s1.h":"Ton solde, et rien d’autre en travers.","wal.s3.h":"Un seul historique pour tout.","wal.s3.p":"Paiements, récompenses de bloc et parts de pool apparaissent au même endroit. Les montants sont exacts jusqu’à la 8e décimale.","wal.s5.h":"Des noms à la place des adresses.","wal.s5.p":"Enregistre un contact une fois, et tous les paiements avec cette personne se retrouvent dans un seul fil.","pay.alt":"De nombreuses petites lumières scintillent, se rassemblent en un point brillant qui devient un bloc, puis des rayons partent du bloc vers chaque adresse qu’il paie.","pay.0.h":"Tout le monde devine en même temps.","pay.0.p":"En ce moment, tout le réseau travaille à environ <span data-live='hashrate'></span> : des milliards de nombres chaque seconde, tous à la recherche du même bloc.","pay.1.h":"Un nombre convient.","pay.1.p":"Environ toutes les dix minutes, une machine trouve un nombre qui convient. C’est un nouveau bloc, et la recherche recommence.","pay.2.h":"Le bloc paie tous ceux qui ont aidé.","pay.2.p":"Dans un pool, la récompense est répartie selon le travail fourni par chaque mineur et payée dans le bloc lui-même. Le dernier bloc de pool a payé <span id='pay-n'></span> adresses d’un coup.","pay.3.h":"Pas de compte. Pas de seuil de paiement. Pas de garde des fonds.","calcx.a":"Ma machine fait","calcx.b":"et je mine","poolsx.last":"des derniers blocs","poolsx.fee":"frais","poolsx.seats":"places occupées","poolsx.rate":"déclaré","shore.on":"En allumer une de plus","shore.off":"L’éteindre à nouveau","shore.note.on":"Le numéro {k} n’est allumé que sur ton écran. Il comptera dès que ton nœud tournera.","node.check.h":"Du bloc 0 à aujourd’hui, sans rien demander à personne.","comm.vote.say":"Le 25 octobre 2026, la communauté a voté sur le début de la révision 6. Elle a choisi le bloc 10 000.","comm.vote.cta":"Ce qu’apporte la révision 6","log.k":"Chaque bloc jusqu’au","log.cap":"Chaque ligne est un jour depuis le 9 septembre 2026 (UTC), chaque trait un bloc à son heure de la journée. Les traits chauds contenaient des transferts. Touche un trait pour ouvrir le bloc.","log.cap.n":"Chaque ligne couvre {d} jours depuis le 9 septembre 2026 (UTC), chaque trait est un bloc. Les traits chauds contenaient des transferts. Touche un trait pour ouvrir le bloc.","log.alt":"Le journal de bord de la chaîne : chaque bloc depuis le bloc 0 sous forme de trait, une ligne par jour.","comm.say":"Jour {d}. {n} nœuds gardent la chaîne, {m} mineurs la prolongent, {p} pools se partagent le travail. Personne n’a été désigné. Ils sont venus.","road.start.k":"25 oct. 2026","road.start":"Le vote","road.end.k":"Bloc 10 000","road.end":"La révision 6 commence","road.now":"Bloc {h} · maintenant","road.left":"Encore {n} blocs. Au rythme actuel, cela fait {eta}.","road.done":"La révision 6 est active depuis le bloc 10 000.","road.need":"Les nœuds ont besoin d’une version récente avant ce bloc.","road.need.done":"Les nœuds restés sur une ancienne version ne suivent plus la chaîne.","coin.turn":"La retourner","coin.turn.back":"La remettre à l’endroit","coin.back.k":"Bloc 0","coin.back.d":"9 septembre 2026","netp.say":"Bloc {h}, trouvé {a}. {r} au travail sur le suivant. {n} nœuds observent.","start.jump":"Les cinq portes d’entrée","start.guides":"Chaque porte d’entrée expliquée pas à pas","story.road.h":"La chaîne jusqu’ici, et ce qui est déjà fixé","story.road.p":"Sept repères le long de la chaîne. Ceux qui sont derrière nous portent leur date. Ceux qui sont devant ne portent qu’un numéro de bloc, parce que c’est tout ce que le code connaît.","story.road.live":"Voir les derniers blocs","miles.left":"dans {n} blocs","forge.hash":"SHA-256, appliqué deux fois","forge.target":"ne doit pas dépasser la cible","forge.ok":"Valide : recalculé sur cet appareil.","forge.nodes":"{n} nœuds signalés","forge.nodes.1":"{n} nœud signalé","forge.paid":"{r} vers {n} adresses","forge.paid.1":"{r} vers {n} adresse","forge.before":"{n} blocs avant lui, espacés comme ils ont été trouvés : {m} min","forge.alt":"Les 136 octets de l’en-tête du bloc le plus récent. Le nonce change jusqu’à ce que le hash passe sous la cible ; les nœuds le vérifient alors, et le bloc prend sa place au bout de la chaîne et paie sa récompense.","term.note.live":"Réponse de l’API publique du {d}.","term.note.snap":"La réponse du {d}. L’API ne répond pas pour le moment ; la page redemande d’elle-même.","term.more":"Afficher les {n} lignes","term.less":"Afficher moins de lignes","term.alt":"Une requête à l’API publique et sa réponse","agol.sec":"il y a {n} secondes","agol.sec.1":"il y a {n} seconde","agol.min":"il y a {n} minutes","agol.min.1":"il y a {n} minute","agol.hours":"il y a {n} heures","agol.hours.1":"il y a {n} heure","agol.days":"il y a {n} jours","agol.days.1":"il y a {n} jour","netp.k":"Le réseau, en direct","netp.k.snap":"Le réseau le {date}","netp.say.snap":"Le bloc {h} était le plus récent. {r} travaillaient sur le suivant. {n} nœuds observaient.","netp.lead.snap":"Le dernier état reçu par cette page. L’API publique ne répond pas pour le moment ; la page redemande d’elle-même.","ex.h1":"Chaque bloc est public.","ex.lead":"Cherche un bloc, un transfert ou une adresse. Ton navigateur recalcule la preuve de travail de chaque bloc qu’il affiche.","ex.q.ph":"Bloc, hash ou adresse","pulse.tip.h":"Les {n} dernières heures","pulse.next":"Le bloc {h} est en cours de minage. {t} depuis le dernier bloc.","pulse.around.h":"Autour du bloc {h}","pulse.around.n":"{n} blocs sur ces {k} heures","pulse.now":"actuelle","pulse.by":"Trouvé par {who}","pulse.alt":"Des blocs sur une ligne de temps. Chaque lumière est un bloc ; l’écart entre deux lumières est le temps qui les sépare.","ex.row.tx":"{n} transferts","ex.row.tx.1":"{n} transfert","ex.row.tx0":"aucun transfert","ex.proof.h":"La preuve de travail","ex.proof.p":"Un mineur fait tourner deux compteurs de l’en-tête, le nonce et l’extranonce, jusqu’à ce que le hash des 136 octets passe sous la cible. Ton navigateur vient de refaire ce calcul.","proof.pick":"Sélectionne un champ pour voir ce qu’il contient.","pulse.around.n.1":"{n} bloc sur ces {k} heures","ex.tx.batch":"Paiement groupé","ex.tx.script":"Dépense d’un compte à script","ex.txv.status":"Statut","ex.txv.waiting":"En attente d’un bloc","ex.txv.sumPending":"Envoyé, mais pas encore dans un bloc.","ex.txv.expected":"Attendu dans le bloc {h}, dans environ {min} min, à condition que rien n’arrive avec des frais plus élevés.","ex.txv.unknownWhen":"Plus loin dans la file que ne porte la prévision.","ex.addr.waiting":"En attente","ex.addr.older":"Charger l’activité plus ancienne","ex.next.tag":"en cours","ex.next.h":"Ce qui est déjà certain","ex.next.reward":"Récompense","ex.next.pending":"Transactions en attente","ex.next.empty":"Le mempool est vide, ce bloc ne contient donc pour l’instant que la coinbase.","ex.next.some":"Les paiements en attente entrent dans ce bloc dans la limite de la place disponible.","ex.next.who":"On ne sait pas encore qui le trouvera.","ex.fill":"{p} % plein","ex.fill.of":"{n} transactions sur {max}","ex.queue.h":"File d’attente","ex.queue.row":"{n} tx · dès {fee} · ~{min} min","ex.queue.none":"Rien n’attend — le prochain bloc prend tout.","ex.queue.more":"{n} transactions dans {b} blocs au total.","ex.queue.note":"Ordre prévu selon les frais par octet, en supposant que rien de nouveau n’arrive. Les frais valent pour un transfert sans note.","ex.check.h":"Vérification dans ton navigateur","ex.check.note":"Ces vérifications se font ici, pas sur le serveur.","ex.check.ser":"Sérialisation","ex.check.hash":"Hash recalculé","ex.check.pow":"Preuve de travail","ex.check.link":"Lien de chaîne","ex.check.ok":"valide","ex.check.bad":"INVALIDE","ex.check.open":"ouvert","ex.check.p":"L’en-tête est reconstruit à partir de ses champs, hashé deux fois, comparé à la difficulté enregistrée, et le lien de chaîne est suivi. Ces vérifications se font ici, pas sur le serveur. Les blocs affichés viennent du miroir du serveur ; il est comparé au nœud complet, et un écart s’affiche ici. Un point vert sur un bloc signifie : vérifié ici.","ex.f.achieved":"Atteinte","ex.f.time":"Temps de bloc","ex.f.time.s":"depuis le bloc précédent","ex.verdict.ok":"{n} blocs vérifiés ici","ex.verdict.ok.1":"{n} bloc vérifié ici","ex.verdict.bad":"Une vérification a échoué","ex.verified":"vérifié ici","ex.mirror.fork":"Le miroir montre à la hauteur {h} un autre bloc que le nœud complet. La liste ci-dessous est peut-être sur une autre branche.","ex.mirror.behind":"Le miroir a {n} blocs de retard sur le nœud complet. Les plus récents manquent ci-dessous.","ex.mirror.behind.1":"Le miroir a {n} bloc de retard sur le nœud complet. Les plus récents manquent ci-dessous.","lv.an.apk.akku":"Certains appareils ferment malgré tout les apps en arrière-plan pour économiser la batterie. Si le minage s’arrête tout seul, règle l’utilisation de la batterie de l’app sur « Non restreinte » (Paramètres → Applications → YSKAR Wallet → Batterie).","lv.an.apk.dienst":"Depuis la version 1.0.9, c’est un service propre à l’app qui calcule. Le minage continue quand tu quittes l’app ou que l’écran est verrouillé. Tant qu’il tourne, Android affiche une notification avec ton hashrate ; « Arrêter le minage » l’arrête directement depuis là.","lv.an.apk.hintergrund":"Miner en arrière-plan","lv.an.apk.inst":"Installation","lv.an.apk.knopf":"Télécharger la dernière version","lv.an.apk.m1":"Ouvre l’onglet Minage et descends jusqu’à « Commandes ».","lv.an.apk.m2":"Choisis le mode : Solo ou Pool. En mode Pool, l’app propose un pool ouvert ; avec « Changer », tu vois tous les pools avec leurs mineurs, leur puissance de hash, leurs blocs trouvés et leurs frais. Un pool complet ne peut pas être choisi.","lv.an.apk.m3":"Règle « Workers » et « Charge ». Les workers sont les cœurs du processeur qui calculent ; la charge indique à quel point ils sont sollicités (de 25 à 100 %).","lv.an.apk.m4":"Touche « Lancer le minage ». Si Android demande l’autorisation des notifications, accepte : tu vois ainsi que le minage tourne et tu peux l’arrêter depuis là.","lv.an.apk.name":"Sur ton téléphone, cette app s’appelle « YSKAR Wallet ». C’est une autre app que la nouvelle YSKAR Wallet sans minage ; les deux peuvent être installées côte à côte et tes 12 mots fonctionnent dans les deux.","lv.an.apk.pruefen":"Vérifier le téléchargement (facultatif)","lv.an.apk.pruefenText":"Chaque version contient aussi un fichier se terminant par <code>.sha256</code>. Il contient la somme de contrôle de l’APK. Si la somme de contrôle de ton téléchargement correspond, le fichier est exactement celui que nous avons publié.","lv.an.apk.s1":"Sur ton téléphone, ouvre la page de téléchargement et touche le fichier <code>yskar-wallet-….apk</code>.","lv.an.apk.s2":"Android demande si les apps de cette source (par exemple ton navigateur) peuvent être installées. Touche « Paramètres » et autorise cette source.","lv.an.apk.s3":"Reviens en arrière et touche « Installer ». Google Play Protect peut afficher un avertissement ; c’est normal pour les apps hors Play Store.","lv.an.apk.s4":"Ouvre l’app, crée un portefeuille ou restaure celui que tu as déjà avec tes 12 mots.","lv.an.apk.start":"Lancer le minage","lv.an.apk.text":"L’app Android continue à miner en arrière-plan, même écran verrouillé, et affiche ton minage dans un widget sur l’écran d’accueil. Comme Google Play n’autorise pas le minage sur l’appareil, cette version est disponible directement chez nous.","lv.an.apk.tipp":"Notre recommandation : tous les workers, charge à 25 %, en pool. Cela ménage la batterie et la température, et en pool de plus petits montants arrivent plus régulièrement. « Calibrer l’appareil » trouve le meilleur nombre de workers pour ton téléphone.","lv.an.apk.titel":"App Android avec minage","lv.an.apk.update":"Mettre l’app à jour","lv.an.apk.updateText":"Quand une nouvelle version existe, l’app affiche un message à l’ouverture. Touche « Télécharger » : l’app récupère la mise à jour, puis Android demande s’il faut l’installer. Ton portefeuille est conservé. Pour vérifier à la main, va dans l’app sous Réglages → App → Mises à jour.","lv.an.apk.w1":"Appuie longuement sur un endroit libre de l’écran d’accueil, choisis « Widgets » et fais glisser « YSKAR Wallet » sur l’écran.","lv.an.apk.w2":"Quand le minage tourne, le widget affiche ce que tu as gagné pendant cette session, ainsi que le hashrate, la durée et les shares acceptés. « Stop » arrête le minage directement depuis l’écran d’accueil. Quand le minage est arrêté, tu vois le bloc actuel, le hashrate du réseau et la récompense de bloc.","lv.an.apk.w3":"« Gagné pendant cette session » compte les récompenses de bloc et les paiements du pool crédités à ton adresse depuis le lancement ; la valeur change quand un nouveau bloc est trouvé. Clair ou sombre se choisit dans l’app, sous Réglages → App → Widget. Le widget sous cette forme existe à partir de la version 1.1.0.","lv.an.apk.widget":"Widget sur l’écran d’accueil","lv.an.etikett":"Guides","lv.an.ex.p1":"Recherche par hauteur de bloc, hash ou adresse.","lv.an.ex.p2":"Pour chaque bloc, tu vois qui l’a trouvé : un nom, un pool ou une adresse solo.","lv.an.ex.p3":"Saisis ta propre adresse pour vérifier les paiements que tu as reçus.","lv.an.ex.text":"L’<a href=\"/explorer\">explorateur</a> affiche chaque bloc, chaque transfert et chaque adresse. Il reconstitue chaque en-tête de bloc dans ton navigateur, le hache et vérifie la preuve de travail et la chaîne. Les transferts, les signatures et les soldes sont vérifiés par les nœuds complets : fais-en tourner un, et tu n’as plus à croire personne.","lv.an.ex.titel":"L’explorateur","lv.an.gr.aus":"Comment un pool paie","lv.an.gr.aus1":"C’est le bloc lui-même qui paie directement chacun. L’opérateur du pool ne détient jamais ton argent, et il n’y a pas de seuil de paiement.","lv.an.gr.aus2":"Ce qui compte, c’est le travail fourni récemment, mesuré en shares. Si tu viens seulement de commencer, ta part du premier bloc est petite en conséquence.","lv.an.gr.gebuehr":"L’opérateur peut prélever des frais de 0 à 5 %. Ils sont indiqués dans la liste des pools.","lv.an.gr.hinweis":"Personne ne peut te promettre un rendement. La fréquence à laquelle tu reçois quelque chose dépend de ta puissance de calcul, de la puissance du réseau et du hasard.","lv.an.gr.p1":"YSKAR est une blockchain à part entière. Un nouveau bloc est trouvé environ toutes les 10 minutes. Celui qui le trouve reçoit la récompense – actuellement 875 YSR – directement sur son adresse.","lv.an.gr.p2":"Pour trouver un bloc, ton appareil essaie des nombres (double SHA-256). Plus tu as de puissance de calcul, plus tes chances sont grandes. La difficulté s’adapte à la puissance de tout le réseau.","lv.an.gr.plaetze":"Un bloc peut payer 64 adresses au maximum ; un pool a donc 64 places au maximum (63 s’il prend des frais). Une place ne compte que tant que tu mines : un nouvel appareil l’occupe 2 minutes à l’essai et la garde en livrant régulièrement des shares. Les places des mineurs qui arrêtent redeviennent libres.","lv.an.gr.pool":"<strong>Pool :</strong> beaucoup cherchent ensemble. Quand le pool trouve un bloc, la récompense est répartie selon le travail fourni. Des montants plus petits, mais plus réguliers.","lv.an.gr.solo":"<strong>Solo :</strong> tu cherches seul. Si tu trouves un bloc, toute la récompense est pour toi. Cela peut prendre longtemps.","lv.an.gr.sp":"Solo ou pool","lv.an.gr.titel":"Comment fonctionne le minage","lv.an.hi.a1":"Android ferme l’app pour économiser la batterie. Règle l’utilisation de la batterie de YSKAR Wallet sur « Non restreinte » (Paramètres → Applications → YSKAR Wallet → Batterie).","lv.an.hi.a2":"Un pool a 64 places au maximum. Une place se libère aussitôt qu’un mineur s’arrête, et jusqu’à 20 minutes après qu’un mineur ne donne plus signe de vie ; réessayer plus tard peut donc marcher. Sinon, choisis un autre pool ou mine en solo. Si ton adresse a déjà une place, d’autres appareils peuvent quand même s’y ajouter.","lv.an.hi.a3":"Le nœud n’a pas encore trouvé d’autre nœud. Vérifie ta connexion Internet et si tu as bien autorisé Node Core quand le pare-feu Windows l’a demandé. Attends ensuite un moment.","lv.an.hi.a4":"Le nœud est encore en cours de synchronisation. Le minage démarre dès que la vue d’ensemble affiche « In sync ».","lv.an.hi.a5":"Le minage avec la carte graphique nécessite une carte NVIDIA, AMD ou Intel avec un pilote à jour. Installe le pilote à jour du fabricant et redémarre Node Core. Avant de miner, chaque carte effectue un autotest ; une carte qui échoue n’est pas utilisée.","lv.an.hi.a6":"Restaure le portefeuille avec les mêmes 12 mots, dans le même ordre. D’autres mots donnent un autre portefeuille.","lv.an.hi.a7":"Pose tes questions dans le <a href=\"https://t.me/+GxAmtTMeG1w1M2Yy\">chat de la communauté sur Telegram</a>. Signale les bugs sur <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a>. Ne communique jamais tes 12 mots : les admins ne t’écrivent jamais en premier.","lv.an.hi.f1":"Le minage sur le téléphone s’arrête tout seul","lv.an.hi.f2":"« Pool full »","lv.an.hi.f3":"Node Core : « No peer connected yet »","lv.an.hi.f4":"Node Core : le minage ne démarre pas","lv.an.hi.f5":"La carte graphique n’est pas trouvée","lv.an.hi.f6":"Mon solde n’apparaît pas sur un nouvel appareil","lv.an.hi.f7":"Autre chose","lv.an.hi.titel":"Si quelque chose ne fonctionne pas","lv.an.mini.hinweis":"Astuce : dans l’onglet Minage, tu peux choisir entre solo et pool. En pool, tu reçois de plus petits montants plus souvent ; en solo, des blocs entiers mais plus rarement.","lv.an.mini.s1":"Ouvre <a href=\"https://t.me/YSKAR_bot\">@YSKAR_bot</a> dans Telegram et lance l’app.","lv.an.mini.s2":"Touche « Créer un portefeuille ». L’app t’affiche 12 mots : note-les sur papier, dans l’ordre.","lv.an.mini.s3":"Confirme quelques-uns des mots et choisis un PIN.","lv.an.mini.s4":"Ouvre l’onglet Minage et touche « Lancer le minage ». Garde l’app ouverte pendant qu’elle calcule.","lv.an.mini.text":"Le moyen le plus rapide. La Mini App tourne dans Telegram ; il n’y a rien à installer.","lv.an.mini.titel":"Mini App Telegram","lv.an.nc.e1":"<strong>Nœud :</strong> le dossier de données, les ports et le seed sont préremplis. Les valeurs par défaut conviennent à la plupart – clique simplement sur « Continue ».","lv.an.nc.e2":"<strong>Portefeuille :</strong> crée un nouveau portefeuille et note les 12 mots, ou reprends ton portefeuille existant avec tes 12 mots. Choisis un mot de passe d’au moins 8 caractères ; il chiffre les mots sur ce PC. Tu peux aussi configurer le portefeuille plus tard.","lv.an.nc.e3":"<strong>Démarrage :</strong> clique sur « Start node ».","lv.an.nc.einst":"Réglages","lv.an.nc.erst":"Premier démarrage","lv.an.nc.firewall":"Au premier démarrage, Windows demande si Node Core peut accéder au réseau. Autorise-le, sinon le nœud ne peut pas trouver d’autres nœuds.","lv.an.nc.firewallLinux":"Sous Linux, cette question n’apparaît pas. Si un pare-feu est actif (comme ufw), ouvre le port 8646 – sinon les autres nœuds ne peuvent pas joindre le tien. Tes propres connexions fonctionnent dans tous les cas.","lv.an.nc.i1":"Télécharge l’installateur et lance-le.","lv.an.nc.i2":"Windows affiche « Windows a protégé votre ordinateur », car l’installateur n’est pas signé. Choisis « Informations complémentaires », puis « Exécuter quand même ».","lv.an.nc.i3":"Suis les étapes de l’installateur. Node Core démarre ensuite.","lv.an.nc.inst":"Installation sous Windows","lv.an.nc.l1":"<strong>Ubuntu, Debian, Linux Mint :</strong> télécharge le fichier <code>.deb</code> et installe-le dans un terminal. Lance ensuite « YSKAR Node Core » depuis le menu des applications.","lv.an.nc.l2":"<strong>Autres distributions :</strong> télécharge l’AppImage, rends-la exécutable et lance-la. Les AppImage ont besoin de FUSE 2 (sous Ubuntu, le paquet <code>libfuse2</code>).","lv.an.nc.l3":"Node Core pour Linux fonctionne sur les PC 64 bits (x86-64) avec un environnement de bureau. Les ordinateurs ARM comme le Raspberry Pi ne sont pas pris en charge.","lv.an.nc.linux":"Installation sous Linux","lv.an.nc.m1":"Choisis la cible : Solo ou Pool. En mode Pool, prends un pool dans la liste ou saisis une adresse sous « Your own pool address » et vérifie-la.","lv.an.nc.m2":"« Reward goes to » : ton propre portefeuille ou une autre adresse.","lv.an.nc.m3":"Choisis l’appareil : processeur, carte graphique ou les deux. Règle le nombre de cœurs et la charge par cœur.","lv.an.nc.m4":"En solo uniquement : si tu veux, saisis un nom qui apparaît dans les blocs que tu trouves. Il est public et permanent.","lv.an.nc.m5":"Clique sur « Start mining ».","lv.an.nc.mining":"Minage","lv.an.nc.poolHinweis":"Si un pool ne t’accepte plus, le minage s’arrête et t’indique pourquoi. Il ne continue jamais en solo sans te le dire.","lv.an.nc.port":"Dois-je ouvrir un port ?","lv.an.nc.portText":"Non. Sans cela, ton nœud se connecte de lui-même à d’autres nœuds. Si tu ouvres le port 8646 dans ton routeur, d’autres nœuds peuvent aussi joindre le tien. Cela aide le réseau, mais c’est facultatif.","lv.an.nc.pruefen":"Pour être sûr que le fichier est bien celui que nous avons publié, compare sa somme de contrôle avec le fichier <code>.sha256</code> de la version. Dans PowerShell :","lv.an.nc.pruefenLinux":"Sous Linux :","lv.an.nc.s1":"<strong>Démarrer avec Windows</strong> (sous Linux : « Démarrer à l’ouverture de session ») : Node Core démarre sans fenêtre quand tu ouvres ta session.","lv.an.nc.s2":"<strong>Continuer à tourner à la fermeture :</strong> la fenêtre disparaît dans la zone de notification à côté de l’horloge, le nœud continue de travailler.","lv.an.nc.s3":"<strong>Reprendre le minage après le démarrage :</strong> le minage reprend avec les derniers réglages dès que le nœud est synchronisé.","lv.an.nc.s4":"<strong>Mises à jour :</strong> Node Core te prévient quand une nouvelle version est disponible. Rien ne s’installe tout seul.","lv.an.nc.sig":"Signer et YSKAR Lab","lv.an.nc.sigText":"Depuis la version 1.1.0, « Signer » dans le portefeuille signe un texte avec ton adresse, par exemple pour prouver qu’une adresse t’appartient ; « Vérifier » contrôle un message signé par quelqu’un d’autre. Sur <a href=\"https://lab.yskar.app\">lab.yskar.app</a>, « Se connecter avec le portefeuille » ouvre Node Core : il affiche le site, ton adresse et la durée de validité de la demande, et ne signe qu’après ta confirmation avec ton mot de passe. Une signature ne peut pas déplacer de YSR.","lv.an.nc.sync":"La première synchronisation","lv.an.nc.syncText":"Au premier démarrage, Node Core télécharge toute la blockchain et vérifie chaque bloc. Cela peut prendre un moment ; la vue d’ensemble affiche la progression. Le minage ne démarre que lorsque le nœud a rattrapé le réseau.","lv.an.nc.text":"Node Core est le programme YSKAR pour Windows et Linux : ton propre nœud avec portefeuille et minage dans une seule fenêtre. Il télécharge la blockchain sur ton PC et vérifie lui-même chaque bloc.","lv.an.nc.titel":"Node Core pour Windows et Linux","lv.an.nc.update":"Mise à jour","lv.an.nc.updateText":"Télécharge le nouvel installateur, quitte Node Core – aussi dans la zone de notification – et lance l’installateur. Ton portefeuille et la blockchain sont conservés.","lv.an.nc.v1":"Windows 10 ou 11 (64 bits) ou Linux (64 bits, x86-64) et une connexion Internet","lv.an.nc.v2":"De l’espace disque pour la blockchain. Elle est encore petite et grandit à chaque bloc.","lv.an.nc.v3":"Pour miner avec la carte graphique : une carte NVIDIA, AMD ou Intel avec un pilote à jour. Sans elle, c’est le processeur qui calcule.","lv.an.nc.vor":"Ce qu’il te faut","lv.an.nc.w1":"<strong>Envoyer :</strong> saisis le destinataire et le montant, vérifie, confirme avec ton mot de passe. Le mot de passe est demandé avant chaque transfert.","lv.an.nc.w2":"<strong>Recevoir :</strong> affiche ton adresse ou son QR code.","lv.an.nc.w3":"<strong>Contacts :</strong> des noms à la place des adresses, enregistrés uniquement sur ce PC.","lv.an.nc.w4":"<strong>Verrouillage :</strong> le portefeuille se verrouille après 10 minutes sans activité et chaque fois que Windows est verrouillé. Tu peux changer cette durée dans les réglages.","lv.an.nc.wallet":"Portefeuille","lv.an.node.s1":"1. Compiler","lv.an.node.s2":"2. Démarrer et se connecter au réseau","lv.an.node.s2Text":"Le nœud se connecte à un autre nœud (le seed), charge la chaîne et la vérifie bloc par bloc. D’autres nœuds peuvent joindre le tien sur le port 8646 si tu l’ouvres dans ton routeur ; c’est facultatif. Avec --no-upstream, ton nœud ne transmet les blocs qu’aux autres nœuds, pas au serveur web du projet.","lv.an.node.s3":"3. Miner sur ton propre nœud","lv.an.node.s4":"4. Gérer un pool (facultatif)","lv.an.node.s4Fuss":"--pool-fee est en points de base : 100 = 1,00 %, 500 au maximum.","lv.an.node.s4Mehr":"Ce dont un pool a besoin pour que l’app et les autres mineurs puissent le joindre est décrit dans <a href=\"/anleitungen#pool\">Faire tourner un pool</a>.","lv.an.node.s4Text":"N’importe quel nœud peut être un pool, sans inscription. C’est le bloc lui-même qui paie tous les participants ; tu ne détiens jamais les fonds des autres.","lv.an.node.s5":"5. En tant que service sur un Raspberry Pi","lv.an.node.s5Text":"Pour que le nœud redémarre tout seul après un redémarrage, configure-le comme service systemd. Les fichiers prêts à l’emploi et un guide se trouvent dans le dépôt sous <a href=\"https://github.com/dabitlex/YSKAR/tree/main/deploy\"><code>deploy/</code></a>.","lv.an.node.text":"Un nœud complet télécharge la chaîne et vérifie lui-même chaque bloc – preuve de travail, signatures, soldes. Il nécessite Node.js 22.13 ou plus récent et tourne bien sur un Raspberry Pi.","lv.an.node.titel":"Faire tourner un nœud complet","lv.an.node.win":"Sous Windows, utilise npm.cmd au lieu de npm.","lv.an.pc.s1":"1. Installer Node.js","lv.an.pc.s1Text":"Le mineur nécessite Node.js 20 ou plus récent. Télécharge la version LTS sur <a href=\"https://nodejs.org\">nodejs.org</a> et installe-la. Sous Windows, ouvre ensuite une nouvelle fenêtre de commande.","lv.an.pc.s2":"2. Récupérer le mineur","lv.an.pc.s2Text":"Il n’y a rien d’autre à installer. L’autotest vérifie que ton ordinateur calcule correctement les hashs.","lv.an.pc.s3":"3. Lancer le minage","lv.an.pc.s3Text":"Remplace l’adresse par ta propre adresse YSKAR (elle commence par ysr1). Avec le pool :","lv.an.pc.s4":"4. Carte graphique (facultatif)","lv.an.pc.s4Text":"Avec une carte graphique, ajoute <code>--gpu</code>. Il faut un programme GPU : <code>yskar-cuda</code> pour les cartes NVIDIA, <code>yskar-opencl</code> pour les cartes AMD et Intel. Le mineur prend le premier qui trouve une carte ; <code>--gpu-api opencl</code> utilise le programme AMD et Intel même si une carte NVIDIA est présente. Pour Linux, les deux sont joints à chaque version de Node Core (<code>yskar-cuda-…-linux-x86_64</code>, <code>yskar-opencl-…-linux-x86_64</code>) ; sous Windows, compile-les comme décrit dans le dépôt sous <code>node-core/gpu</code>.","lv.an.pc.s5":"5. Rigs de minage sous HiveOS","lv.an.pc.s5Text":"Pour les rigs de minage sous HiveOS, il existe un paquet prêt à l’emploi : ce mineur avec le programme GPU, un mineur par carte NVIDIA, AMD ou Intel, sans frais. Il est joint à chaque version de Node Core sous le nom <code>yskar-hiveos-….tar.gz</code>. La configuration de la flight sheet est décrite dans <a href=\"https://github.com/dabitlex/YSKAR/blob/main/hiveos/README.md\">hiveos/README.md</a>.","lv.an.pc.solo":"En solo plutôt qu’en pool : retire --mode pool. Des blocs entiers, mais plus rarement.","lv.an.pc.text":"Le mineur tourne sous Windows, macOS et Linux. Il n’a besoin que d’une adresse – pas de clé privée, pas de portefeuille, pas d’inscription. Tu peux le lancer sans risque sur n’importe quel ordinateur.","lv.an.pc.titel":"Mineur PC","lv.an.pool.beitritt":"Comment les mineurs rejoignent le pool","lv.an.pool.beitrittText":"Dans l’app, choisis « Pool » et saisis l’adresse de ton pool sous « Adresse personnalisée » ; dans Node Core, sous « Your own pool address ». Avec le mineur PC :","lv.an.pool.caddy":"La configuration pour Caddy. Remplace le nom par le tien ; il doit d’abord pointer vers ta machine.","lv.an.pool.g1":"<strong>Nom :</strong> 3 à 32 caractères simples. Il est inscrit dans chaque bloc de ton pool et y reste pour toujours.","lv.an.pool.g2":"<strong>Frais :</strong> 0 à 5 %. Dans la commande, <code>--pool-fee</code> est indiqué en points de base : 100 = 1 %. Avec des frais, tu dois indiquer l’adresse à laquelle ils vont.","lv.an.pool.g3":"<strong>Places :</strong> 64 adresses au maximum, 63 avec des frais – l’un des destinataires, c’est toi.","lv.an.pool.g4":"<strong>Pas d’argent des autres :</strong> le bloc paie directement chacun. Tu ne détiens jamais les fonds de tes mineurs.","lv.an.pool.h1":"Ouvre « Run a pool », définis le nom, les frais et le nombre de places, puis active-le.","lv.an.pool.h2":"Sous Minage, choisis « Pool ». Ton propre pool apparaît en premier.","lv.an.pool.h3":"Pour d’autres PC, active « Devices in your home network ». Ils se connectent avec <code>http://&lt;adresse de ce PC&gt;:8645</code>.","lv.an.pool.heim":"Dans ton réseau domestique avec Node Core","lv.an.pool.heimText":"Le pool de Node Core ne répond qu’à ton propre PC et à ton propre réseau. De cette façon, il n’est pas joignable depuis Internet.","lv.an.pool.k1":"Qui mine avec toi","lv.an.pool.k2":"Ce qu’il te faut","lv.an.pool.liste":"Figurer dans la liste des pools","lv.an.pool.listeText":"L’app et Node Core affichent une liste de pools tenue à jour. Pour y figurer, ton pool doit être joignable en HTTPS et répondre à <code>/api/v2/pool</code>. Fais-en la demande sur <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a>. La liste n’est ni une vérification ni une recommandation : un pool indique lui-même ses mineurs, sa puissance et ses frais.","lv.an.pool.n1":"<strong>Un nœud qui tourne en permanence.</strong> Le mieux est le nœud en ligne de commande sur un Raspberry Pi ou un serveur ; voir <a href=\"/anleitungen#fullnode\">Faire tourner un nœud complet</a>.","lv.an.pool.n2":"<strong>Un nom</strong> sous lequel il est joignable : ton propre domaine ou un nom DynDNS gratuit.","lv.an.pool.n3":"<strong>HTTPS avec un certificat valide.</strong> Telegram et les navigateurs ne chargent rien qui ne soit pas chiffré. Sans HTTPS, aucun téléphone ne peut joindre ton pool.","lv.an.pool.n4":"<strong>Un serveur web placé devant</strong> qui récupère le certificat et transmet les requêtes au nœud, par exemple Caddy.","lv.an.pool.n5":"<strong>Le port 443 ouvert.</strong> Pour un nœud à la maison, cela veut dire une redirection de port dans ton routeur.","lv.an.pool.netz":"Pour l’app, la Mini App et les mineurs depuis Internet","lv.an.pool.netzText":"Voici ce qu’il te faut :","lv.an.pool.o1":"<strong>À la maison :</strong> pas de coût supplémentaire. Mais ton adresse IP devient publique, il te faut une redirection de port, et c’est ta connexion qui supporte la charge.","lv.an.pool.o2":"<strong>Serveur loué :</strong> ton adresse IP à la maison reste en dehors de tout ça, et aucune clé n’est stockée sur le serveur – seulement l’adresse pour les frais. Lis d’abord les conditions du fournisseur : beaucoup interdisent le minage ou tout ce qui s’y rapporte. Fais-toi confirmer l’autorisation par écrit.","lv.an.pool.ort":"À la maison ou sur un serveur loué ?","lv.an.pool.r1a":"Toi et les appareils de ton réseau domestique","lv.an.pool.r1b":"Node Core avec « Run a pool » activé","lv.an.pool.r2a":"Des mineurs PC depuis Internet","lv.an.pool.r2b":"Un nœud qui tourne en permanence et qui est joignable de l’extérieur","lv.an.pool.r3a":"L’app et la Mini App","lv.an.pool.r3b":"En plus, HTTPS : un nom (domaine ou DynDNS) et un certificat","lv.an.pool.regeln":"Règles pour chaque pool","lv.an.pool.start":"Démarre le nœud en tant que pool. Il n’écoute que sur la machine elle-même ; le serveur web se trouve devant lui.","lv.an.pool.test":"Vérifie depuis l’extérieur. Si la réponse contient le nom de ton pool et le nombre de places, le pool est joignable.","lv.an.pool.text":"Un pool YSKAR n’est pas un service avec des comptes. C’est un nœud qui répartit la récompense de ses blocs. Chacun peut en gérer un, sans inscription. Ce qu’il te faut dépend de qui doit miner avec toi.","lv.an.pool.titel":"Gérer un pool","lv.an.si.p1":"<strong>Tes 12 mots sont ton portefeuille.</strong> Ne les saisis jamais sur un site web, ne les envoie jamais à personne. Personne chez YSKAR ne te les demandera.","lv.an.si.p2":"<strong>Télécharge uniquement depuis yskar.app et le projet YSKAR sur GitHub.</strong> Si tu veux être sûr, compare la somme de contrôle.","lv.an.si.p3":"<strong>Garde tes logiciels à jour.</strong> Lors d’un changement de règles annoncé, un nœud obsolète soit s’arrête à ce bloc, soit continue sans vérifier la nouvelle règle – deux bonnes raisons de mettre à jour à temps.","lv.an.si.p4":"<strong>Si tu fais tourner un nœud :</strong> les autres nœuds voient ton adresse IP, comme dans tout réseau pair à pair. Tu n’as pas besoin d’une redirection de port. Si tu ne veux pas que ton adresse soit visible, utilise un VPN.","lv.an.si.p5":"<strong>Node Core :</strong> le portefeuille et l’interface ne sont accessibles que depuis ton propre PC.","lv.an.si.titel":"Sécurité","lv.an.text":"Tout est expliqué pas à pas : le minage sur le téléphone et sur PC, ton portefeuille, ton propre nœud et ton propre pool.","lv.an.titel":"Étape par étape","lv.an.tocLabel":"Sur cette page","lv.an.ue.k1":"Voie","lv.an.ue.k2":"Convient pour","lv.an.ue.k3":"Il te faut","lv.an.ue.r1a":"Mini App Telegram","lv.an.ue.r1b":"Essayer, tout de suite","lv.an.ue.r1c":"Telegram","lv.an.ue.r2a":"App Android","lv.an.ue.r2b":"Miner en arrière-plan sur le téléphone","lv.an.ue.r2c":"Un téléphone Android","lv.an.ue.r3a":"Node Core","lv.an.ue.r3b":"Ton propre nœud avec portefeuille et minage sur PC, carte graphique comprise","lv.an.ue.r3c":"Windows 10/11 ou Linux (64 bits)","lv.an.ue.r4a":"Mineur PC","lv.an.ue.r4b":"Miner en ligne de commande","lv.an.ue.r4c":"Windows, macOS ou Linux avec Node.js","lv.an.ue.r5a":"Nœud complet","lv.an.ue.r5b":"Un nœud ou un pool sur un Raspberry Pi ou un serveur","lv.an.ue.r5c":"Linux, Windows ou macOS avec Node.js 22.13 ou plus récent","lv.an.ue.text":"Il y a cinq voies pour participer. Toutes utilisent le même portefeuille : avec tes 12 mots, tu retrouves partout le même solde.","lv.an.ue.titel":"Quelle voie te convient ?","lv.an.w.empfangen":"Recevoir","lv.an.w.empfangenText":"Affiche ton adresse ou son QR code. Tu peux ajouter un montant et une note au code ; l’expéditeur n’a alors plus qu’à confirmer. Tu peux donner ton adresse à tout le monde – tes 12 mots à personne.","lv.an.w.kontakte":"Contacts et historique","lv.an.w.kontakteText":"Les contacts donnent un nom aux adresses ; ils sont enregistrés uniquement sur ton appareil. L’historique affiche chaque paiement ; les gains de minage d’une journée sont regroupés sur une seule ligne, que tu peux ouvrir jusqu’au bloc individuel.","lv.an.w.s1":"Destinataire : colle l’adresse, scanne le QR code ou choisis un contact. Une adresse YSKAR commence par ysr1.","lv.an.w.s2":"Montant et, si tu veux, une note de 32 octets au maximum – soit 32 lettres latines simples, moins avec des accents ou d’autres écritures. La note est enregistrée publiquement dans la blockchain.","lv.an.w.s3":"Frais : l’app les propose. Quand le réseau n’est pas chargé, les frais minimaux suffisent pour le prochain bloc.","lv.an.w.s4":"Vérification : l’app affiche l’adresse complète et t’indique si tu as déjà envoyé à cette adresse. Confirme avec ton PIN ou ton empreinte digitale.","lv.an.w.senden":"Envoyer","lv.an.w.warn":"Un paiement envoyé ne peut pas être récupéré. Vérifie toute l’adresse avant de confirmer.","lv.an.wallet.p1":"Note les mots sur papier, dans le bon ordre. Pas de capture d’écran, pas de cloud.","lv.an.wallet.p2":"Garde le papier en lieu sûr. Si tu perds ton téléphone, les mots restaurent tout.","lv.an.wallet.p3":"Le PIN protège seulement l’app sur cet appareil. Il ne remplace pas les mots.","lv.an.wallet.p4":"Pour passer à un nouvel appareil, choisis « J’ai déjà mes douze mots » et saisis-les.","lv.an.wallet.text":"Ton portefeuille est créé sur ton appareil à partir de 12 mots. Ces mots sont ta clé : qui les possède a accès aux fonds – sur n’importe quel appareil, dans n’importe quelle app YSKAR.","lv.an.wallet.titel":"Ton portefeuille","lv.fuss.datenschutz":"Confidentialité","lv.fuss.impressum":"Mentions légales","lv.hood.f2.k":"Difficulté","lv.nc.appimage":"AppImage pour les autres distributions Linux","lv.nc.bildNotiz":"Vue d’exemple : les chiffres sont des exemples.","lv.nc.knopfLinux":"Télécharger pour Linux (.deb)","lv.nc.knopfWin":"Télécharger pour Windows","lv.nc.mehr":"Somme de contrôle et notes de version","lv.nc.system":"Windows 10 ou 11 (64 bits)","lv.nc.systemLinux":"Linux 64 bits · Ubuntu, Debian, Mint","lv.pr.block.alt":"L’en-tête de bloc de 136 octets et ses dix champs","lv.pr.block.merkle":"Un hash sur toutes les transactions du bloc. Un seul octet modifié dans n’importe quel transfert le change.","lv.pr.block.nonce":"Le nombre que font varier les mineurs. Les 128 premiers octets restent les mêmes pour une tâche, si bien que chaque essai ne demande que deux étapes de compression SHA-256.","lv.pr.block.prev":"Le hash du bloc précédent. Il relie la chaîne : modifier un ancien bloc changerait tous les hashs qui suivent.","lv.pr.block.state":"Un hash sur tous les comptes (solde et nonce) après ce bloc. Chaque nœud le calcule lui-même et compare.","lv.pr.block.text":"Chaque bloc commence par exactement 136 octets. Son hash est un double SHA-256 de ces octets, et il ne doit pas dépasser la cible fixée par la difficulté.","lv.pr.block.titel":"Anatomie d’un en-tête de bloc","lv.pr.db.ablauf":"Expiration","lv.pr.db.ablaufWert":"facultative, par hauteur de bloc","lv.pr.db.adresse":"Adresse","lv.pr.db.adresseWert":"ysr1…, 42 caractères ; comptes partagés depuis V6 : ysr1p…, 63 caractères (bech32m)","lv.pr.db.blockzeitWert":"600 secondes (cible)","lv.pr.db.diffWert":"LWMA sur 45 blocs, à chaque bloc","lv.pr.db.einheit":"Plus petite unité","lv.pr.db.gebuehr":"Les frais vont à","lv.pr.db.gebuehrWert":"le mineur du bloc","lv.pr.db.kette":"La chaîne","lv.pr.db.knoten":"Nœuds complets","lv.pr.db.knotenWert":"chacun conserve et vérifie toute la chaîne","lv.pr.db.konsens":"Consensus","lv.pr.db.konsensWert":"Preuve de travail, SHA-256d","lv.pr.db.memo":"Note","lv.pr.db.memoWert":"jusqu’à 32 octets","lv.pr.db.minGeb":"Frais minimaux (consensus)","lv.pr.db.minGebWert":"1 unité par octet","lv.pr.db.modell":"Modèle","lv.pr.db.modellWert":"comptes avec solde et nonce","lv.pr.db.muenze":"La pièce","lv.pr.db.name":"Nom · symbole","lv.pr.db.netz":"Réseau","lv.pr.db.notfall":"Règle d’urgence","lv.pr.db.notfallWert":"plus facile après 30 min sans bloc","lv.pr.db.nullkonto":"Adresse de destruction","lv.pr.db.pfad":"Dérivation des clés","lv.pr.db.pool":"Pools","lv.pr.db.poolWert":"payés depuis le bloc, frais 0–5 %","lv.pr.db.relay":"Frais minimaux pour le relais","lv.pr.db.relayWert":"10 unités par octet","lv.pr.db.sig":"Signatures","lv.pr.db.staub":"Plus petit montant envoyable","lv.pr.db.staubWert":"100 unités","lv.pr.db.transfer":"Taille d’un transfert","lv.pr.db.transferWert":"168 à 200 octets","lv.pr.db.tx":"Transactions par bloc","lv.pr.db.txWert":"jusqu’à 2 000","lv.pr.db.vorab":"Pré-minage · attribution","lv.pr.db.vorabWert":"aucun","lv.pr.db.wahl":"Choix de la chaîne","lv.pr.db.wahlWert":"le plus de travail cumulé","lv.pr.db.wallet":"Portefeuilles et comptes","lv.pr.db.worte":"Mots de récupération","lv.pr.db.worteWert":"BIP39, 12 ou 24 mots","lv.pr.etikett":"Le protocole en détail","lv.pr.gen.belohnung":"Récompense","lv.pr.gen.belohnungWert":"875 YSR, non dépensables","lv.pr.gen.text":"Le premier bloc de la chaîne. Sa coinbase porte un court message, et sa récompense est allée à une adresse depuis laquelle personne ne peut dépenser.","lv.pr.gen.titel":"Bloc 0","lv.pr.gen.zeit":"Horodatage","lv.pr.pruefen":"Vérifie toi-même le bloc 0 ou le dernier bloc, directement dans ton navigateur.","lv.pr.text":"Tout ce qui suit est fixé dans le code de consensus et identique pour chaque nœud. Rien ne dépend d’un serveur, d’une entreprise ou d’un réglage.","lv.pr.titel1":"YSKAR et YSR,","lv.pr.titel2":"octet par octet.","lv.pr.tx.alt":"Champs d’un transfert","lv.pr.tx.p1":"La signature couvre aussi l’identifiant de chaîne : un transfert signé pour YSKAR n’est donc valide sur aucun autre réseau.","lv.pr.tx.p2":"Le nonce compte les transferts qu’un compte a envoyés. Un même transfert ne peut jamais être appliqué deux fois.","lv.pr.tx.p3":"Une hauteur d’expiration facultative fait expirer un transfert s’il n’a pas été inclus d’ici là.","lv.pr.tx.text":"Un transfert déplace des YSR d’un compte à un autre. Il fait 168 octets, plus une note facultative.","lv.pr.tx.titel":"Anatomie d’un transfert","lv.recht.nurDeutsch":"Cette page est en allemand, comme l’exige le droit allemand.","lv.supply.aera.fuss":"Les récompenses sont comptées en unités de base entières (0,00000001 YSR) ; chaque halving laisse donc tomber le reste : au total, 20 999 999,99832 YSR seront émis, un peu moins que le maximum.","lv.supply.aera.k1":"Époque","lv.supply.aera.k2":"Blocs","lv.supply.aera.k3":"Récompense par bloc","lv.supply.aera.k4":"Émis dans l’époque","lv.supply.aera.k5":"Total après l’époque","lv.supply.aera.text":"Une époque dure 12 000 blocs, soit environ 83 jours. À chaque époque, la récompense est la moitié de celle de l’époque précédente. À partir du bloc 444 000, aucun nouveau YSR n’est créé et les mineurs ne reçoivent plus que les frais.","lv.supply.aera.titel":"Émission par époque","lv.wallet.warnung":"<strong>Qui a les 12 mots a les fonds.</strong> Ne les partage jamais. Personne chez YSKAR ne te les demandera.","lv.wpseite.drucken":"Imprimer / enregistrer en PDF","lv.wpseite.toc":"Sommaire","lv.wpseite.untertitel":"Une blockchain à preuve de travail que chacun peut miner et que chacun peut vérifier.","lv.zahlen.blockzeit":"Temps de bloc","lv.wpseite.nurDeEn":"Le livre blanc est pour l’instant disponible en anglais et en allemand.","unit.min":"{n} min","unit.hours":"{n} heures","unit.days":"{n} jours","ago.sec":"il y a {n} s","ago.min":"il y a {n} min","ago.hours":"il y a {n} h","ago.days":"il y a {n} jours","eta.around":"dans environ {d}, vers le {date}","v6.active":"Active depuis le bloc 10 000","v6.pending":"encore {n} blocs","mode.live":"En direct depuis la chaîne","mode.snapshot":"État du {date}","mode.history":"Historique jusqu’au bloc {h}","mode.liveShort":"Disponible","mode.snapshotShort":"Dernier état connu","dur.years":"{n} ans","dur.years.big":"{n} d’années","dur.days":"{n} jours","dur.hours":"{n} heures","dur.min":"{n} minutes","dur.sec":"{n} secondes","dur.sec.1":"{n} seconde","rm.run.p":"Publié et utilisé. Chaque entrée mène à l’endroit où tu peux le vérifier.","rm.run.1.h":"Réseau principal","rm.run.1.p":"Des blocs depuis le 9 sept. 2026. La chaîne en est au bloc","rm.run.1.l":"Le réseau, en direct","rm.run.2.h":"Révisions du consensus 2 à 5","rm.run.2.p":"Actives depuis les blocs 2 000, 4 000, 6 000 et 7 000.","rm.run.2.l":"Ce que chacune a changé","rm.run.3.p":"Nœud complet, portefeuille, minage CPU et GPU et exploitation de pool pour Windows et Linux.","rm.run.3.l":"Télécharger","rm.run.4.p":"Le portefeuille Android : envoyer, recevoir, signer. Prêt pour la révision 6.","rm.run.4.l":"À propos du portefeuille","rm.run.5.h":"Trois pools publics","rm.run.5.p":"YSKAR MAIN, Gozero et ODW.Serv. Le logiciel de pool est ouvert ; chacun peut en faire tourner un.","rm.run.5.l":"Les pools, en direct","rm.run.6.h":"Explorateur et API publique","rm.run.6.p":"Chaque bloc, transfert et adresse, dans le navigateur et en HTTP.","rm.run.6.l":"Ouvrir l’explorateur","rm.run.7.p":"Propositions, discussions et avancement au grand jour. Tu te connectes avec ton portefeuille.","rm.fix.p":"Ces changements sont écrits dans le code de consensus. Ils prennent effet à un bloc et non à une date : le moment où ce bloc arrive dépend de la vitesse à laquelle les blocs sont trouvés.","rm.fix.blocks":"blocs","rm.fix.1.at":"Bloc 10 000","rm.fix.1.h":"Révision 6","rm.fix.1.p":"Comptes partagés avec jusqu’à 16 clés, verrous temporels et verrous de hash, transferts groupés vers jusqu’à 1 000 destinataires et place pour 5 000 transactions par bloc. Un hard fork, fixé après un vote de la communauté le 25 oct. 2026. Les nœuds doivent tourner sur une version récente avant ce bloc.","rm.fix.1.l":"Ce qui change au bloc 10 000","rm.fix.2.at":"Bloc 12 000","rm.fix.2.h":"Premier halving","rm.fix.2.p":"La récompense de bloc passe de 875 à 437,5 YSR. Elle est de nouveau divisée par deux tous les 12 000 blocs.","rm.fix.2.l":"Le calendrier complet","rm.fix.after":"Le dernier nouveau YSR est créé au bloc 443 999. Ensuite, les mineurs ne touchent plus que les frais.","rm.plan.p":"Envisagé, pas promis. Rien ici n’a de date, et l’ordre peut changer.","rm.plan.1.h":"Swaps et paiements instantanés","rm.plan.1.p":"La révision 6 apporte les briques de base à la chaîne : verrous de hash et verrous temporels. Les fonctions du portefeuille qui s’en servent pour les swaps et les paiements en temps réel viendront après.","rm.plan.2.h":"Stratum pour les rigs de minage","rm.plan.2.p":"Aujourd’hui, mineurs et pools parlent le protocole HTTP propre à YSKAR. Stratum est prévu pour le moment où le réseau aura grandi.","rm.plan.3.h":"Miner vers des comptes partagés","rm.plan.3.p":"La révision 6 ne peut pas verser une récompense de bloc à un compte partagé. La spécification laisse cela à la révision 7.","rm.plan.4.h":"Le portefeuille avec ton propre nœud","rm.plan.4.p":"Aujourd’hui, YSKAR Wallet lit les soldes sur le serveur public. Prévu : le faire pointer vers un nœud complet que tu fais tourner toi-même.","rm.plan.5.h":"YSKAR Wallet sur le Play Store","rm.plan.5.p":"Aujourd’hui, le portefeuille est un APK publié dans les Releases GitHub.","rm.plan.6.h":"Réseau de test public et décisions de la communauté","rm.plan.6.p":"Les prochaines étapes du YSKAR Lab : essayer les changements avant qu’ils n’atteignent le réseau principal, et en décider ensemble.","rm.plan.7.h":"Cotations sur des plateformes d’échange","rm.plan.7.p":"En préparation, sans date et sans noms. Aujourd’hui, YSR n’a ni prix ni marché, et personne ne devrait miner en espérant que cela change.","rm.how.p":"Les propositions sont rédigées, discutées et suivies en public sur le YSKAR Lab. Un changement des règles de consensus exige une spécification, et il n’atteint le réseau principal qu’à une hauteur de bloc que chaque nœud connaît à l’avance.","com.ch.p":"Les annonces paraissent d’abord sur le canal Telegram. Tout le reste sert aux questions et aux discussions.","com.ch.1":"Versions et nouveautés.","com.ch.2":"Questions et discussions avec d’autres mineurs et utilisateurs.","com.ch.3":"Brèves nouvelles de @yskar_official.","com.ch.4":"Le fil d’annonces.","com.ch.5":"Code source, versions et tickets.","com.ch.6":"Propositions, de la première idée à la version publiée.","com.do.1.h":"Faire tourner un nœud complet","com.do.1.p":"Chaque nœud qui vérifie lui-même les blocs rend le réseau moins dépendant d’un seul serveur.","com.do.2.h":"Miner, seul ou dans un pool","com.do.2.p":"Une puissance de hachage répartie entre de nombreux mineurs et plusieurs pools rend la chaîne plus difficile à orienter.","com.do.3.h":"Gérer un pool","com.do.3.p":"Le logiciel de pool fait partie du dépôt et paie les mineurs dans le bloc lui-même. Un pool indépendant de plus répartit encore davantage la puissance de hachage.","com.do.4.h":"Tester et signaler","com.do.4.p":"Essaie une version et ouvre un ticket pour ce qui casse. Dis ce que tu as vu et comment le reproduire.","com.do.5.h":"Proposer et discuter","com.do.5.p":"Apporte une idée au YSKAR Lab, ou améliore celle de quelqu’un d’autre dans les commentaires.","com.lab.p":"Chaque proposition passe par les mêmes six étapes, et tout le monde peut voir où elle en est.","com.lab.s1":"Idée","com.lab.s1.d":"Partage ce que tu as en tête.","com.lab.s2":"Discussion","com.lab.s2.d":"Améliorez-la ensemble dans les commentaires.","com.lab.s3":"Brouillon","com.lab.s3.d":"Texte, design, spécification ou code.","com.lab.s4":"Prévu","com.lab.s4.d":"Fixé pour une prochaine version, avec une justification.","com.lab.s5":"Sur le testnet","com.lab.s5.d":"Essaie-le avant qu’il n’atteigne le réseau principal.","com.lab.s6":"Publié","com.lab.s6.d":"Publié, avec un lien vers la version.","com.lab.k1":"L’auteur fait avancer une proposition à travers les trois premières étapes.","com.lab.k2":"À partir de « Prévu », c’est l’équipe qui fixe l’étape, toujours avec une justification.","com.lab.open":"Ouvrir YSKAR Lab","com.safe.1.h":"Tes 12 mots restent avec toi","com.safe.1.p":"Personne chez YSKAR ne te demandera jamais tes 12 mots, ton code PIN ou un fichier de portefeuille. Celui qui les demande cherche à prendre tes pièces.","com.safe.2.h":"Télécharge à la source","com.safe.2.p":"Récupère les logiciels dans les versions GitHub vers lesquelles ce site renvoie, et compare l’empreinte du certificat du portefeuille avant de l’installer.","com.safe.3.h":"Pas de promesses","com.safe.3.p":"YSR n’a ni prix ni marché aujourd’hui, et il n’est coté sur aucune plateforme d’échange. Rien ici ne promet que cela changera.","com.channel":"Canal Telegram","com.chat":"Chat de la communauté","wallet.dl":"Télécharge l’APK","wallet.meta":"Version 2.0.0, pour Android 7 ou plus récent. Open source sous licence MIT. En anglais et en allemand.","wallet.feat.p":"Pas de publicité, pas de pistage et pas de compte chez qui que ce soit. L’app parle au réseau YSKAR et à rien d’autre.","wallet.f1.h":"Ta clé reste avec toi","wallet.f1.p":"Le portefeuille est créé sur ton téléphone. 12 mots de récupération le restaurent sur n’importe quel appareil. Ils sont stockés chiffrés avec ton code PIN dans le stockage protégé d’Android et ne vont jamais dans les sauvegardes cloud.","wallet.f2.h":"Envoyer en connaissance de cause","wallet.f2.p":"Saisis une adresse, choisis un contact ou scanne un code QR. Avant l’envoi, tu revois le destinataire, le montant et les frais de réseau, puis tu fais glisser pour confirmer. Un transfert ne peut pas être annulé.","wallet.f3.h":"Recevoir et demander","wallet.f3.p":"Montre ton code QR ou ton adresse. Si tu veux, demande un montant précis : l’expéditeur n’a alors plus qu’à confirmer.","wallet.f5.h":"Signer et se connecter","wallet.f5.p":"Prouve par un message signé qu’une adresse est à toi, et vérifie les signatures des autres. Connecte-toi au YSKAR Lab avec un code QR. Une signature ne peut pas déplacer de YSR.","wallet.f6.h":"Bien verrouillé","wallet.f6.p":"Code PIN et empreinte digitale, verrouillage automatique après le délai de ton choix, pas de captures d’écran tant que les 12 mots sont affichés, et un clavier propre à l’app, pour qu’aucune saisie ne passe par l’application de clavier de ton téléphone.","wallet.inst.h":"Installer en quatre étapes","wallet.inst.p":"Le portefeuille est distribué sous forme d’APK via ses versions GitHub. Les mises à jour s’installent par-dessus la version précédente et ton portefeuille reste sur l’appareil.","wallet.inst.1":"Ouvre la <a class='ext' href='https://github.com/dabitlex/YSKAR--WALLET/releases/latest' target='_blank' rel='noopener'>dernière version</a> sur ton téléphone Android et télécharge le fichier <code>yskar-wallet-…apk</code>.","wallet.inst.2":"Ouvre le fichier. Autorise l’installation depuis cette source quand Android le demande.","wallet.inst.3":"Touche « Create wallet » et note les 12 mots sur papier, dans l’ordre.","wallet.inst.4":"Choisis un code PIN. Pour reprendre un portefeuille existant, saisis plutôt ses 12 mots.","wallet.verify.h":"Vérifier que le fichier est authentique","wallet.verify.p":"Chaque version est signée avec la même clé. Voici l’empreinte SHA-256 de son certificat. Si l’empreinte de ton téléchargement est différente, n’installe pas le fichier.","wallet.oth.h":"D’autres endroits pour tes YSR","wallet.oth.p":"Toutes les apps YSKAR utilisent les mêmes 12 mots. Avec eux, tu retrouves le même solde partout.","wallet.oth.1.h":"YSKAR Wallet","wallet.oth.1.p":"Android. Envoyer, recevoir, signer. Il ne mine pas.","wallet.oth.2.h":"Node Core","wallet.oth.2.p":"Windows et Linux. Un portefeuille dans ton propre nœud complet, avec minage et signature de messages. <a href='/mining#setup'>Obtenir Node Core</a>","wallet.oth.3.h":"App Android avec minage","wallet.oth.3.p":"Portefeuille et minage sur le téléphone, avec un widget d’écran d’accueil et des notifications.","wallet.oth.4.h":"Mini App Telegram","wallet.oth.4.p":"L’entrée la plus simple, sans rien installer. La propriété dépend de tes 12 mots, pas de ton compte Telegram.","wallet.st.h":"Où en est le portefeuille","wallet.st.1.h":"Android uniquement","wallet.st.1.p":"Le portefeuille est un APK publié sur GitHub. Il n’est dans aucune boutique d’applications, et il n’existe pas d’app iOS.","wallet.st.2.h":"Prêt pour la révision 6","wallet.st.2.p":"La version 2.0.0 connaît le nouveau format de transfert et y passe au bloc 10 000. Une version plus ancienne reçoit toujours des YSR, mais ne peut plus en envoyer après ce bloc.","wallet.st.3.h":"Prévu : une boutique d’applications","wallet.st.3.p":"Une publication sur Google Play est prévue. Il n’y a pas de date.","wallet.st.4.h":"Prévu : ton propre nœud","wallet.st.4.p":"Aujourd’hui, le portefeuille lit les données du nœud principal du projet. Il est prévu de pouvoir le connecter à un nœud que tu fais tourner toi-même, afin que personne n’ait à croire le projet sur parole pour un solde.","mining.ways.p":"Toutes les voies sont gratuites et utilisent le même portefeuille : avec tes 12 mots, tu retrouves les mêmes YSR partout.","mining.tab.pc":"PC","mining.tab.phone":"Téléphone","mining.tab.cli":"Ligne de commande","mining.tab.rig":"Rig","mining.pc.h":"Node Core pour Windows et Linux","mining.pc.p":"Un nœud complet, un portefeuille et un mineur dans un seul programme. Node Core vérifie lui-même chaque bloc et mine avec ton processeur et avec des cartes graphiques NVIDIA, AMD et Intel. Version 1.1.0, pour Windows 10 et 11 et pour Linux 64 bits.","mining.pc.s1":"Télécharge l’installateur et lance-le.","mining.pc.s2":"Crée un portefeuille et note les 12 mots, ou reprends ton portefeuille grâce à eux.","mining.pc.s3":"Dans Mining, choisis solo ou un pool, sélectionne processeur ou carte graphique, puis démarre.","mining.pc.win":"Télécharger pour Windows","mining.pc.deb":"Télécharger pour Linux (.deb)","mining.pc.more":"Également disponibles : une <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/download/node-core-v1.1.0/YSKAR-Node-Core-1.1.0-x86_64.AppImage' target='_blank' rel='noopener'>AppImage</a> pour les autres distributions Linux, et les <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/tag/node-core-v1.1.0' target='_blank' rel='noopener'>notes de version avec les sommes de contrôle</a>.","mining.pc.note":"<strong>L’installateur Windows n’est pas signé.</strong> Windows pose donc la question une fois : choisis « Informations complémentaires », puis « Exécuter quand même ». Compare la somme de contrôle avec les notes de version si tu veux être sûr que le fichier est bien celui qui a été publié.","mining.pc.imgcap":"Node Core, vue d’ensemble. Les chiffres de l’image sont des exemples.","mining.phone.h":"Sur ton téléphone","mining.phone.p":"La façon la plus simple de découvrir YSKAR. Un téléphone apporte peu de puissance de hachage et ne trouve des blocs que dans un pool. Le minage sérieux se fait sur des PC et des rigs.","mining.phone.s1":"Installe l’app Android depuis GitHub, ou ouvre la Mini App dans Telegram.","mining.phone.s2":"Crée un portefeuille et note les 12 mots sur papier.","mining.phone.s3":"Choisis un pool et commence à miner.","mining.phone.apk":"App Android avec minage","mining.phone.tg":"Mini App dans Telegram","mining.phone.f1":"App Android","mining.phone.f1.v":"Continue de miner en arrière-plan, même écran verrouillé, et affiche l’état dans un widget d’écran d’accueil. Distribuée sous forme d’APK, car les boutiques d’applications n’autorisent pas le minage sur l’appareil.","mining.phone.f2":"Mini App","mining.phone.f2.v":"Rien à installer. Fonctionne dans Telegram tant qu’il est ouvert. Tes pièces dépendent de tes 12 mots, pas de ton compte Telegram.","mining.phone.f3":"YSKAR Wallet","mining.phone.f3.v":"L’app de portefeuille ne mine pas. Elle est faite pour envoyer, recevoir et signer.","mining.cli.h":"Le mineur en ligne de commande","mining.cli.p":"Pour Windows, macOS et Linux. Le mineur n’a besoin que d’une adresse : pas de clé, pas de portefeuille et pas d’inscription. Tu peux le faire tourner sur un ordinateur que tu ne contrôles pas.","mining.cli.f1":"Prérequis","mining.cli.f1.v":"Node.js 20 ou plus récent, rien d’autre à installer","mining.cli.f2":"Cartes graphiques","mining.cli.f2.v":"ajoute <code>--gpu</code>. Il utilise <code>yskar-cuda</code> pour NVIDIA et <code>yskar-opencl</code> pour AMD et Intel","mining.cli.f3":"Solo","mining.cli.f3.v":"mine sur ton propre nœud complet et retire <code>--mode pool</code>","mining.cli.link":"Le guide complet du mineur","mining.cli.c1":"récupérer le mineur et tester cet ordinateur","mining.cli.c2":"miner dans le pool public","mining.cli.c3":"ou en solo, sur ton propre nœud","mining.cli.addr":"Remplace <code>ysr1...</code> par ta propre adresse. Les récompenses y arrivent directement.","mining.rig.h":"Rigs de minage sous HiveOS","mining.rig.p":"Un paquet prêt pour HiveOS : le mineur en ligne de commande avec les programmes GPU, un mineur par carte graphique.","mining.rig.dl":"Télécharger le paquet 1.1.0","mining.rig.doc":"Flight sheet et configuration","mining.rig.f1":"Cartes","mining.rig.f1.v":"NVIDIA (CUDA), AMD et Intel (OpenCL)","mining.rig.f2":"Frais","mining.rig.f2.v":"aucuns dans le mineur. Chaque pool garde ses propres frais","mining.rig.f3":"Configuration","mining.rig.f3.v":"ton adresse et le pool vont dans le flight sheet. Le guide montre chaque champ","mining.return":"<strong>Personne ne peut te promettre un rendement.</strong> La fréquence à laquelle tu reçois quelque chose dépend de ta puissance de hachage, de celle de tout le réseau et du hasard. YSR n’a pas de prix de marché.","pools.p1":"En solo, tu cherches seul et tu gardes toute la récompense d’un bloc que tu trouves. Dans un pool, beaucoup cherchent ensemble et la récompense est répartie selon le travail fourni par chacun.","pools.p2":"Un pool YSKAR n’est pas un service avec des comptes. C’est un nœud dont les blocs paient directement chaque mineur, dans le bloc lui-même. L’opérateur ne détient jamais les pièces d’autrui, et il n’y a pas de seuil de paiement.","pools.reported":"{r} déclarés","pools.c5":"Sur les {n} derniers","pools.full":"complet","pools.cap":"Mineurs, places et hashrate sont ce que chaque pool déclare sur lui-même. La part des {n} derniers blocs est comptée à partir de la chaîne.","pools.f1":"Répartition","pools.f1.v":"Selon les parts du passé récent (PPLNS). Si tu viens de commencer, ta part du premier bloc est petite.","pools.f2":"Places","pools.f2.v":"Un bloc peut payer au plus 64 adresses ; un pool a donc 63 places, plus les frais de l’opérateur. À partir de la révision 6, ce sera 254.","pools.f3":"Frais","pools.f3.v":"Fixés par l’opérateur, entre 0 et 5 %.","pools.f4":"Ton propre pool","pools.f4.v":"N’importe quel nœud peut être un pool, sans inscription. <a class='ext' href='https://github.com/dabitlex/YSKAR/blob/main/docs/POOL.md' target='_blank' rel='noopener'>Comment en faire tourner un</a>","calc.p":"Saisis ton hashrate. L’estimation utilise le travail des derniers blocs de la chaîne, pas les chiffres que les pools déclarent sur eux-mêmes. Node Core et le mineur affichent ton hashrate pendant qu’ils tournent.","calc.unit":"Unité","calc.mode":"Comment tu mines","calc.pool":"En pool","calc.solo":"Solo","calc.which":"Pool","calc.day":"Par jour, en moyenne","calc.week":"Par période de 7 jours","calc.month":"Sur 30 jours","calc.share":"Ta part du réseau","calc.d.every":"Intervalle moyen entre deux blocs","calc.d.chance":"Probabilité d’au moins un bloc en 24 heures","calc.d.block":"Par bloc que tu trouves","calc.d.poolEvery":"Intervalle moyen entre deux blocs du pool","calc.d.part":"Ta part de chaque bloc du pool","calc.d.fee":"Frais du pool, déjà déduits","calc.d.poolShare":"Part du pool dans les {n} derniers blocs","calc.d.net":"Hashrate du réseau d’après les {n} derniers blocs","calc.enter":"Saisis un hashrate supérieur à 0.","calc.note":"Une estimation, pas une promesse. Les blocs sont trouvés par hasard, et la difficulté suit l’ensemble du réseau. Les frais ne sont pas inclus.","calc.halving":"Le halving au bloc {b} aura lieu dans environ {d} jours. Les chiffres sur 7 et 30 jours comptent déjà la moitié de la récompense après lui.","calc.halving.1":"Le halving au bloc {b} aura lieu dans environ un jour. Les chiffres sur 7 et 30 jours comptent déjà la moitié de la récompense après lui.","calc.every.min":"{n} minutes","calc.every.min.1":"{n} minute","calc.every.hours":"{n} heures","calc.every.days":"{n} jours","calc.every.years":"{n} ans","net.hashrate":"Hashrate du réseau","net.difficulty":"Difficulté","net.now":"En ce moment","net.height":"Hauteur de bloc","net.fromChain":"travail des 24 derniers blocs, divisé par leur durée","net.everyBlock":"recalculée à chaque bloc","net.blocktime":"Temps de bloc, 50 derniers blocs","net.target600":"cible : 600 s","net.mempool":"Transferts en attente","net.fromNode":"sur le nœud principal","net.miners":"Mineurs actifs","net.sessions":"Sessions de minage","net.nodes":"Nœuds qui se signalent","net.reported":"déclaré, non vérifiable","net.next.v6":"Révision 6 au bloc 10 000","net.next.halving":"Premier halving au bloc 12 000","net.hist.h":"Historique, lu dans les blocs","net.hist.p":"Chaque bloc de la chaîne, additionné par jour en UTC. L’historique est complet jusqu’au bloc <span data-live='snapTip'></span> ; les chiffres ci-dessus sont lus en direct.","net.range":"Période","net.range.all":"Depuis le bloc 0","net.range.30":"30 jours","net.range.7":"7 jours","net.c.hash":"Hashrate par jour","net.c.hash.capLog":"Travail des blocs du jour divisé par leur durée. Échelle logarithmique : chaque ligne vaut dix fois celle du dessous.","net.c.hash.capLin":"Travail des blocs du jour divisé par leur durée.","net.c.blocks":"Blocs par jour","net.c.blocks.cap":"Jours complets uniquement. Au temps de bloc cible, une journée compte 144 blocs.","net.c.blocks.ref":"Cible : 144 blocs par jour","net.c.blocks.name":"blocs","net.c.finders":"Blocs par jour, selon qui les a trouvés","net.c.finders.cap":"Jours complets uniquement. Les blocs de pool portent le nom du pool dans la chaîne ; un bloc qui paie une seule adresse compte comme solo.","net.c.time":"Temps de bloc moyen par jour","net.c.time.cap":"Secondes entre les blocs, en moyenne sur la journée.","net.c.time.ref":"Cible : 600 secondes","net.c.day":"Jour (UTC)","net.s.main":"YSKAR MAIN","net.s.gozero":"Gozero","net.s.solo":"Solo","net.find.h":"Qui trouve les blocs","net.find.p1":"Les premières semaines, chaque bloc était trouvé en solo. Aujourd’hui, presque tous les blocs viennent de deux pools, et la plupart d’un seul.","net.find.p2":"Cela compte. L’opérateur d’un pool choisit les transactions et le bloc parent de chaque bloc sur lequel le pool travaille, et celui qui dirige la majeure partie de la puissance de hachage peut construire la chaîne ayant le plus de travail. Davantage de pools et de mineurs solo rendent la chaîne plus difficile à orienter.","net.find.link":"Les pools, et comment faire tourner le tien","net.find.title":"Part des blocs trouvés","net.find.last":"{n} derniers blocs","net.find.last1000":"Les 1 000 blocs jusqu’au bloc {h}","net.find.allb":"Tous les blocs jusqu’au bloc {h}","net.find.cap":"Compté à partir de la chaîne. La première barre suit la chaîne en direct, les deux autres s’arrêtent là où s’arrête l’historique embarqué dans la page.","net.blocks.h":"Les derniers blocs","net.blocks.p":"Sélectionne un bloc pour voir son en-tête, recalculer sa preuve de travail et lire ses transactions.","net.blocks.link":"Ouvrir l’explorateur","net.blocks.title":"Les plus récents d’abord","net.b.height":"Hauteur","net.b.age":"Trouvé","net.b.by":"Par","net.b.paid":"Payé à","net.b.diff":"Difficulté","net.b.solo":"solo","net.b.addr":"{n} adresses","net.b.addr.1":"{n} adresse","net.src.h":"D’où viennent les chiffres","net.src.p":"Tous les chiffres de cette page n’ont pas le même poids.","net.src.1.h":"De la chaîne","net.src.1.p":"Hauteur, difficulté, offre et tous les graphiques de cette page. Le hashrate est le travail des derniers blocs divisé par le temps qu’ils ont pris. Quiconque fait tourner un nœud complet peut tout recalculer.","net.src.2.h":"Déclaré","net.src.2.p":"Mineurs actifs, sessions, nœuds et hashrate qu’un pool annonce pour lui-même. Ce sont des déclarations. Elles indiquent une tendance, et personne ne peut les vérifier.","net.src.3.h":"Le miroir","net.src.3.p":"Cette page et l’explorateur lisent une copie de la chaîne en base de données, pour se charger vite. Le miroir vérifie chaque bloc qu’il stocke, mais c’est une commodité. La chaîne, c’est ce sur quoi les nœuds complets s’accordent.","net.src.4.h":"Nœuds d’amorçage","net.src.4.p":"Un nouveau nœud contacte d’abord <code>pool.yskar.app:8646</code> ou <code>yskar-seed2.dynv6.net:8646</code>. Les deux sont gérés par le même opérateur. Ensuite, les nœuds s’échangent entre eux les adresses d’autres nœuds.","ex.q.label":"Rechercher dans la chaîne","ex.q.go":"Rechercher","ex.try":"Pour commencer :","ex.try.0":"le bloc 0","ex.try.burn":"la destruction au bloc 3 974","ex.try.or":"ou","ex.try.zero":"l’adresse depuis laquelle personne ne peut dépenser","ex.crumb":"Explorateur","ex.msg.empty":"Saisis une hauteur de bloc, un hash de bloc, un ID de transaction ou une adresse.","ex.msg.badAddr":"Cette adresse contient une faute de frappe : sa somme de contrôle ne correspond pas. Vérifie-la caractère par caractère.","ex.msg.addrShape":"Ce n’est pas une adresse YSKAR. Les adresses commencent par ysr1 et comptent 42 caractères.","ex.msg.tooHigh":"Le bloc {h} n’existe pas encore. La chaîne en est au bloc {tip}.","ex.msg.notFound":"Rien dans la chaîne ne correspond à cette recherche.","ex.msg.offlineHash":"La chaîne ne répond pas pour le moment, ce hash ne peut donc pas être recherché. Réessaie dans un instant.","ex.msg.searching":"Recherche dans la chaîne.","ex.msg.badLink":"Ce lien ne mène ni à un bloc, ni à une transaction, ni à une adresse.","ex.loading":"Lecture depuis la chaîne.","ex.missing.h":"La chaîne ne répond pas pour le moment","ex.missing.p":"L’explorateur lit chaque bloc, chaque transfert et chaque adresse via l’API publique de YSKAR, et cette requête vient d’échouer. Il réessaie de lui-même dès que la chaîne répond.","ex.missing.link":"Réessayer maintenant","ex.none.block":"La chaîne n’a pas de bloc {h}. Elle en est au bloc {tip}.","ex.none.tx":"Aucune transaction avec cet ID n’est connue : elle n’est dans aucun bloc et n’en attend aucun. Si tu l’as envoyée il y a un instant, cette page revérifie d’elle-même.","ex.back":"Retour aux derniers blocs","ex.latest.h":"Derniers blocs","ex.latest.snap":"La chaîne ne répond pas pour le moment. Voici les {n} derniers blocs tels qu’à la dernière réponse.","ex.latest.live":"Lu via l’API publique et actualisé toutes les 45 secondes.","ex.older":"Afficher les blocs plus anciens","ex.older.busy":"Lecture","ex.c.height":"Hauteur","ex.c.found":"Trouvé","ex.c.by":"Par","ex.c.transfers":"Transferts","ex.c.size":"Taille","ex.c.hash":"Hash du bloc","ex.solo":"Mineur solo","ex.bytes":"{n} octets","ex.block.h":"Bloc {h}","ex.prev":"Bloc précédent","ex.next":"Bloc suivant","ex.block.sumPool":"Trouvé le {date}, {ago}, par le pool {who}.","ex.block.sumSolo":"Trouvé le {date}, {ago}, par un mineur solo.","ex.block.sumGenesis":"Le premier bloc de la chaîne, daté du {date}. Sa récompense est allée à une adresse depuis laquelle personne ne peut dépenser.","ex.block.partial":"La chaîne ne répond pas pour le moment. Voici l’en-tête du bloc tel que la page l’avait déjà ; tu peux donc toujours vérifier sa preuve de travail. Ses transactions suivront dès que la chaîne répondra.","ex.block.values":"Ce que dit l’en-tête","ex.block.values.p":"Ces valeurs sont regroupées dans les 136 octets ci-dessus. Change l’une d’elles et le hash ne correspond plus.","ex.f.hash":"Hash du bloc","ex.f.prev":"Bloc précédent","ex.f.prev.none":"Aucun. C’est le premier bloc.","ex.f.merkle":"Racine de Merkle","ex.f.merkle.s":"Empreinte des transactions de ce bloc","ex.f.state":"Racine d’état","ex.f.state.s":"Empreinte de tous les soldes après ce bloc","ex.f.diff":"Difficulté","ex.f.diff.s":"Tentatives nécessaires en moyenne : environ {n}","ex.f.nonce":"Nonce et extranonce","ex.f.nonce.s":"Les deux compteurs que le mineur a fait tourner jusqu’à ce que le hash convienne","ex.f.size":"Taille","ex.f.size.v":"{n} octets avec {tx} transactions","ex.f.size.v.1":"{n} octets avec {tx} transaction","ex.txs.h":"Transactions de ce bloc","ex.txs.p":"La première crée la récompense de bloc. Toutes les autres sont des transferts signés par leur expéditeur.","ex.tx.coinbase":"Récompense de bloc","ex.tx.transfer":"Transfert","ex.tx.other":"Transaction de type {type}","ex.tx.new":"{a} nouvellement créés","ex.tx.newFees":"{a} nouvellement créés et {f} de frais","ex.tx.from":"De","ex.tx.to":"À","ex.tx.amount":"Montant","ex.tx.fee":"Frais","ex.tx.memo":"Note","ex.tx.memoHex":"Note (octets)","ex.tx.nonce":"Compteur de l’expéditeur","ex.tx.nonce.s":"Chaque transfert d’une adresse porte le numéro suivant, si bien qu’aucun ne peut être rejoué","ex.tx.id":"ID de la transaction","ex.tx.paid":"Payé dans le bloc lui-même à {n} adresses. Le pool n’a jamais détenu ces pièces.","ex.tx.c.addr":"Adresse","ex.tx.c.amount":"Montant en YSR","ex.tx.c.share":"Part","ex.unspendable":"non dépensable","ex.txv.sum":"Confirmé dans le bloc {h} le {date}.","ex.txv.block":"Bloc","ex.txv.until":"Expiration","ex.txv.until.none":"Aucune expiration définie","ex.txv.until.h":"Bloc {h}","ex.txv.size":"Taille","ex.txv.raw":"Les octets tels qu’ils figurent dans le bloc","ex.txv.raw.p":"Un nœud vérifie exactement ces octets : la signature, le solde de l’expéditeur et le compteur.","ex.txv.how":"Comment un transfert est construit","ex.addr.h":"Adresse","ex.addr.zero":"Personne ne détient de clé pour cette adresse. Ce qui arrive ici ne pourra plus jamais être dépensé.","ex.addr.balance":"Solde","ex.addr.sent":"Transferts envoyés","ex.addr.first":"Première apparition","ex.addr.last":"Dernière activité","ex.addr.blockN":"Bloc {h}","ex.addr.solo":"Récompenses de bloc reçues","ex.addr.pool":"Paiements de pool reçus","ex.addr.hist":"Activité récente","ex.addr.more":"Les {n} dernières entrées.","ex.addr.none":"La chaîne n’a encore aucune entrée pour cette adresse. Une adresse est valide dès que sa clé existe ; la chaîne en prend connaissance au premier paiement.","ex.h.block":"Bloc","ex.h.when":"Quand","ex.h.what":"Quoi","ex.h.with":"Avec","ex.h.amount":"Montant","ex.h.fee":"Frais","ex.k.in":"Reçu","ex.k.out":"Envoyé","ex.k.reward":"Récompense de bloc","ex.k.pool":"Paiement de pool","ex.copy.addr":"Copier l’adresse","ex.copy.id":"Copier l’ID","ex.block.sumPoolNoName":"Trouvé le {date}, {ago}, par un pool.","dev.node.h":"Faire tourner un nœud complet","dev.node.p":"Un nœud complet conserve sa propre copie de la chaîne et vérifie lui-même chaque bloc. Il ne croit rien sur parole, ni les autres nœuds ni ce site.","dev.node.link":"Ce qu’un nœud vérifie dans chaque bloc","dev.node.c1":"Récupère le code source et compile le nœud","dev.node.c2":"Démarre-le : il se connecte aux nœuds d’amorçage, télécharge la chaîne et vérifie chaque bloc","dev.node.c3":"Mine sur ton propre nœud, dans un second terminal","dev.node.f1.k":"Il te faut","dev.node.f1.v":"Node.js 22.13 ou plus récent et Git. Le nœud stocke la chaîne avec le module SQLite intégré à Node.js.","dev.node.f2.k":"Ports","dev.node.f2.v":"TCP 8646 pour les autres nœuds, 8645 pour l’interface HTTP qu’utilisent les mineurs et les portefeuilles.","dev.node.f3.k":"Horloge","dev.node.f3.v":"Garde l’horloge du système à l’heure. Un bloc daté de plus de 120 secondes en avance sur l’horloge de ton nœud est rejeté.","dev.node.f4.k":"Nœuds d’amorçage","dev.node.f4.v":"Le nœud en ligne de commande n’a aucun seed intégré. Indique les deux nœuds d’amorçage, comme dans la commande ci-dessus.","dev.node.f5.k":"<code>--no-upstream</code>","dev.node.f5.v":"À mettre dans la commande. Sans lui, le nœud échangerait aussi des blocs avec le miroir en base de données du projet, qui n’accepte que les blocs du nœud principal.","dev.node.core":"Sous Windows, tape <code>npm.cmd</code> à la place de <code>npm</code> dans PowerShell. Si tu préfères une fenêtre à un terminal, <a href=\"/node#core\">Node Core</a> fait tourner le même nœud complet sous Windows et Linux.","dev.api.h":"Lire la chaîne via HTTP","dev.api.p":"L’API publique répond en JSON à de simples requêtes GET. Choisis une requête et lis la réponse.","dev.api.title":"Console API","dev.api.pick":"Requêtes","dev.api.out":"Réponse","dev.api.run":"Renvoyer","dev.api.curl":"Copier en curl","dev.api.busy":"En attente de la réponse.","dev.api.ok":"{status} en {ms} ms, réponse en direct de www.yskar.app.","dev.api.fail":"La requête a échoué ({why}). Voici la dernière réponse reçue par cette page, datée du {date}.","dev.api.e.summary":"Hauteur, difficulté, hashrate, offre","dev.api.e.blocks":"Les derniers blocs, du plus récent au plus ancien","dev.api.e.block":"Un bloc avec toutes ses transactions","dev.api.e.tx":"Une transaction par son ID","dev.api.e.account":"Solde et historique d’une adresse","dev.api.e.search":"À quoi correspond ce texte ?","dev.api.e.fees":"Les frais qu’il faut à un transfert en ce moment","dev.api.e.pools":"Les pools et les chiffres qu’ils déclarent","dev.api.e.supply":"Miné, non dépensable et en circulation","dev.api.e.circ":"L’offre en circulation sous forme de simple nombre","dev.api.n1.h":"En lecture seule et ouverte","dev.api.n1.p":"Ni clé ni compte. Les requêtes inter-origines sont autorisées, une page web peut donc appeler l’API directement.","dev.api.n2.h":"Ton propre nœud répond aussi","dev.api.n2.p":"Chaque nœud complet sert les mêmes routes de lecture sur le port 8645. Pointe ton code vers <code>http://127.0.0.1:8645</code> et tu ne dépends du serveur de personne.","dev.api.n3.h":"Les montants sont des nombres entiers","dev.api.n3.p":"Les montants sont exprimés en unités : 1 YSR vaut 100 000 000 unités. Lis-les comme des entiers ou des chaînes, jamais comme des nombres à virgule flottante.","dev.docs.h":"Les documents","dev.docs.p":"Écrits pour celles et ceux qui veulent vérifier ce qui est affirmé. Chacun renvoie au code qu’il décrit.","dev.docs.v6":"La spécification de référence de la révision 6, active à partir du bloc 10 000.","dev.docs.fullnode":"Le nœud complet en ligne de commande : commandes, options, interface HTTP, stockage et réorganisations.","dev.docs.p2p":"Le protocole que les nœuds parlent entre eux.","dev.docs.fees":"Les règles de frais et la façon dont l’estimation des frais est établie.","dev.docs.pool":"Pools : en rejoindre un, en faire tourner un, et le fonctionnement de la comptabilité.","dev.docs.ops":"L’infrastructure publique : nœud principal, HTTPS, miroir et ses réglages.","dev.repo.h":"Où se trouve quoi","dev.repo.p":"Un seul dépôt contient le code du consensus, le nœud, le mineur et les tests qui les protègent.","dev.repo.core":"Consensus : en-tête, difficulté, transactions, état, dérivation du portefeuille","dev.repo.fullnode":"Nœud complet : chaîne, mempool, interface de minage, API de lecture, ligne de commande","dev.repo.p2p":"Le protocole entre nœuds","dev.repo.pool":"Comptabilité PPLNS et répartition de la récompense de bloc","dev.repo.node":"Build du nœud complet en ligne de commande","dev.repo.nodecore":"Node Core pour Windows et Linux, avec les mineurs GPU","dev.repo.miner":"Le mineur en ligne de commande, sans dépendances","dev.repo.observer":"L’observateur : un petit outil en lecture seule qui télécharge la chaîne et recalcule chaque bloc","dev.repo.tests":"Tests du consensus, du nœud, du P2P, du pool et du portefeuille","dev.repo.docs":"La documentation citée ci-dessus","dev.repo.c1":"Depuis la racine du dépôt : installe, lance les tests, vérifie les types","dev.sign.h":"Messages signés","dev.sign.p":"Un portefeuille peut prouver qu’il contrôle une adresse sans déplacer la moindre pièce. Tous les logiciels YSKAR signent et vérifient le même format de texte.","dev.sign.1":"La signature est une signature Ed25519 sur les octets UTF-8 bruts du message entier, vérifiée selon la même règle que sur la chaîne.","dev.sign.2":"La première ligne le rend sûr : une transaction est binaire et ne commence jamais par ces mots, un message signé ne peut donc jamais valoir comme transfert.","dev.sign.3":"YSKAR Wallet et Node Core signent ces messages. YSKAR Lab s’en sert pour te connecter sans mot de passe.","dev.con.h":"Contribuer et signaler","dev.con.1.h":"Modifications du code","dev.con.1.p":"<a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/blob/main/CONTRIBUTING.md\" target=\"_blank\" rel=\"noopener\">CONTRIBUTING.md</a> indique quelles vérifications doivent passer avant un push : les vérifications de types et la suite de tests complète.","dev.con.2.h":"Idées et propositions","dev.con.2.p":"Les propositions pour le protocole et le logiciel sont discutées ouvertement sur <a class=\"ext\" href=\"https://lab.yskar.app\" target=\"_blank\" rel=\"noopener\">YSKAR Lab</a>. Tu te connectes avec ton portefeuille.","dev.con.3.h":"Problèmes de sécurité","dev.con.3.p":"Signale-les sous forme d’issue sur <a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/issues\" target=\"_blank\" rel=\"noopener\">github.com/dabitlex/YSKAR/issues</a>. Les issues sont publiques : décris ce que tu as vu et comment le reproduire, et ne publie jamais tes 12 mots, un PIN, un fichier de portefeuille ou une clé.","ysr.now.blocks":"blocs","ysr.bar.circ":"En circulation","ysr.bar.burned":"Brûlés","ysr.bar.open":"Pas encore émis","ysr.bar.cap":"Parts des 21 000 000 de YSR qui pourront jamais exister.","ysr.sched.title":"Émission selon la hauteur de bloc","ysr.sched.series":"émis","ysr.sched.when.past":"déjà miné","ysr.sched.when.future":"vers le {date}, à 600 s par bloc","ysr.t.all":"Afficher les 37 époques","ysr.t.less":"Afficher les 8 premières époques","ysr.t.now":"actuelle","ysr.fees.h":"Frais","ysr.fees.p":"Un transfert paie des frais aux mineurs du bloc qui l’inclut. Les règles ne fixent qu’un plancher. Au-dessus, le prix suit la demande de place dans un bloc.","ysr.fees.f1":"Plancher fixé par le consensus","ysr.fees.f1.v":"1 unité par octet","ysr.fees.f2":"Plancher pour être relayé","ysr.fees.f2.v":"10 unités par octet. C’est un réglage des nœuds, pas une règle du consensus.","ysr.fees.f3":"Un transfert simple de 168 octets","ysr.fees.f3.v":"au minimum, en ce moment","ysr.fees.f4":"Lent, normal, rapide","ysr.fees.f4.v":"Les trois niveaux ne diffèrent que lorsque les blocs sont pleins. Sinon, les frais minimaux suffisent pour le prochain bloc.","ysr.fees.f5":"Plus petit montant","ysr.fees.f5.v":"100 unités, soit 0,000001 YSR","ysr.fees.f6":"Transferts en attente d’un bloc","ysr.noprice.h":"Pas de prix, pas de promesse","ysr.noprice.p1":"YSR n’a ni prix ni marché, et il n’est coté sur aucune plateforme d’échange. Rien sur ce site ne promet que cela changera, et personne ne devrait miner dans cette attente.","ysr.noprice.p2":"Ce que YSR a, c’est un ensemble de règles que chacun peut vérifier : un maximum fixe, un calendrier d’émission public et des pièces que seule la clé de leur propriétaire peut déplacer.","tech.header.h":"Un bloc commence par 136 octets","tech.header.p1":"L’en-tête désigne le bloc précédent, s’engage sur chaque transaction et sur chaque solde après le bloc, et porte le nonce trouvé par le mineur. Le hash du bloc est un SHA-256, appliqué deux fois, sur exactement ces octets.","tech.header.p2":"La longueur est choisie à dessein. SHA-256 travaille par blocs de 64 octets, et tout sauf le nonce se trouve dans les 128 premiers. Un mineur calcule cette partie une fois par tâche ; chaque essai supplémentaire coûte deux étapes de compression.","tech.pow.h":"Un travail que chacun peut vérifier","tech.pow.p1":"Un bloc n’est valide que si son hash, lu comme un nombre, n’est pas supérieur à une cible. La cible découle de la difficulté. Il n’y a pas de raccourci : la seule façon de trouver un tel hash est d’essayer des nonces, et vérifier le résultat demande deux calculs de hash.","tech.pow.p2":"Une unité de difficulté correspond à 65 536 tentatives attendues. À la difficulté actuelle de <span class='mono' data-live='difficulty'></span>, le nombre de tentatives qu’il faut au réseau pour un bloc est d’environ <span data-live='attempts'></span>.","tech.diff.h":"La difficulté suit le réseau","tech.diff.p1":"La difficulté est recalculée à chaque bloc à partir des 45 derniers blocs. Les blocs récents comptent plus que les anciens, la chaîne réagit donc vite quand de la puissance de hachage arrive ou repart.","tech.diff.p2":"Chaque nœud calcule la même plage à partir des mêmes blocs et rejette un bloc qui annonce une difficulté en dehors. Seuls des nombres entiers sont utilisés, deux nœuds ne peuvent donc jamais arrondir différemment.","tech.diff.chart":"Difficulté depuis le bloc 1","tech.diff.cap":"Moyenne par tranche de 24 blocs jusqu’au bloc <span data-live='snapTip'></span>. L’échelle est logarithmique : chaque ligne vaut dix fois celle du dessous.","tech.diff.f1":"Fenêtre","tech.diff.f1.v":"les 45 derniers blocs, les plus récents pesant le plus","tech.diff.f2":"Plus grand pas","tech.diff.f2.v":"un facteur 4 à la hausse ou à la baisse par bloc","tech.diff.f3":"Temps de résolution pris en compte","tech.diff.f3.v":"de 1 à 3 600 secondes par bloc","tech.diff.f4":"Règle d’urgence","tech.diff.f4.v":"après 1 800 secondes sans bloc, l’exigence baisse en proportion du temps d’attente","tech.diff.f5":"Horodatages","tech.diff.f5.v":"postérieurs à la médiane des 11 derniers blocs, au plus 120 secondes en avance sur l’horloge du nœud","tech.acc.h":"Comptes et transferts","tech.acc.p1":"YSKAR tient un solde et un nonce par adresse. Un transfert indique l’expéditeur, le destinataire, le montant et les frais, et il est signé avec la clé de l’expéditeur. Sans cette clé, personne ne peut déplacer les pièces.","tech.acc.p2":"La racine d’état de chaque en-tête s’engage sur tous les soldes. Un nœud qui rejoue la chaîne depuis le bloc 0 arrive aux mêmes soldes que tous les autres nœuds, ou bien il rejette le bloc.","tech.tx.title":"Un transfert, 168 octets","tech.tx.p":"Plus une note facultative de 32 octets au maximum. Tailles en octets.","tech.tx.aria":"Les champs d’un transfert et leurs tailles en octets","tech.tx.f1":"Version et type","tech.tx.f2":"Adresse de l’expéditeur","tech.tx.f3":"Adresse du destinataire","tech.tx.f4":"Montant","tech.tx.f5":"Frais","tech.tx.f6":"Nonce de l’expéditeur","tech.tx.f7":"Hauteur d’expiration et longueur de la note","tech.tx.f8":"Clé publique","tech.tx.f9":"Signature","tech.acc.f1":"Valable une seule fois","tech.acc.f1.v":"Le nonce doit être égal au nombre de transferts déjà effectués par l’expéditeur, si bien qu’un même transfert ne peut jamais être appliqué deux fois.","tech.acc.f2":"Lié à ce réseau","tech.acc.f2.v":"La signature couvre l’identifiant de chaîne. Un transfert signé pour YSKAR n’est valide nulle part ailleurs.","tech.acc.f3":"Expiration","tech.acc.f3.v":"Un expéditeur peut indiquer une dernière hauteur de bloc. Au-delà, le transfert ne pourra plus jamais être inclus.","tech.acc.f4":"Note","tech.acc.f4.v":"Jusqu’à 32 octets, stockés publiquement dans la chaîne.","tech.acc.f5":"Frais minimaux","tech.acc.f5.v":"1 unité par octet selon le consensus. Les nœuds relaient à partir de 10 unités par octet. Les frais vont aux mineurs du bloc.","tech.acc.f6":"Un transfert simple coûte","tech.acc.f6.v":"en ce moment, au minimum","tech.key.aria":"De 12 mots à une adresse","tech.key.1":"Mots de récupération","tech.key.2":"Chemin de dérivation","tech.key.3":"Paire de clés","tech.key.4":"Adresse","tech.key.p":"Un portefeuille, ce sont 12 ou 24 mots (BIP39). La clé en est dérivée sur l’appareil (SLIP-0010), et l’adresse correspond aux 20 premiers octets du hash SHA-256 de la clé publique, écrits en bech32m. Les mots ne quittent jamais l’appareil qui les a créés.","tech.nodes.h":"Chaque nœud vérifie chaque bloc","tech.nodes.p1":"Un nœud complet stocke toute la chaîne et n’accepte un bloc qu’après l’avoir entièrement vérifié, qu’il vienne d’un autre nœud ou de son propre mineur. Les vérifications se déroulent dans cet ordre.","tech.nodes.link":"Faire tourner un nœud complet","tech.check.1":"Version, 2 000 transactions au maximum, exactement une transaction de récompense en première position, et la racine des transactions.","tech.check.2":"Le hash de l’en-tête, appliqué deux fois, n’est pas supérieur à la cible de la difficulté annoncée.","tech.check.3":"La hauteur est celle du bloc parent plus un, et le hash précédent est le hash du parent.","tech.check.4":"Postérieur à la médiane des 11 derniers blocs, pas antérieur au parent, et au plus 120 secondes en avance sur l’horloge du nœud.","tech.check.5":"La difficulté annoncée se situe dans la plage qui découle des blocs précédents.","tech.check.6":"Signature, expéditeur, nonce, solde, frais et expiration de chaque transfert. La transaction de récompense paie exactement la récompense de bloc plus les frais.","tech.check.7":"La racine calculée sur tous les comptes après le bloc est égale à la racine d’état de l’en-tête.","tech.nodes.chain.h":"Quelle chaîne compte","tech.nodes.chain.p":"La chaîne valide qui a le plus de travail cumulé, le travail d’un bloc étant sa difficulté. Un nœud conserve les blocs concurrents et bascule quand une autre branche a plus de travail.","tech.nodes.pool.h":"Des pools sans conservation des fonds","tech.nodes.pool.p":"La transaction de récompense d’un bloc peut payer jusqu’à 64 adresses. La comptabilité d’un pool devient cette transaction : la chaîne paie donc directement chaque mineur, et l’opérateur ne détient jamais les pièces de qui que ce soit. <a href='/mining#pools'>Comment fonctionnent les pools</a>","tech.rev.h":"Les règles changent à une hauteur de bloc","tech.rev.p":"Un changement de règle est inscrit dans le code avec la hauteur à laquelle il commence. Tous les nœuds basculent au même bloc, et chaque bloc sous cette hauteur garde ses règles, octet pour octet.","tech.rev.c1":"Révision","tech.rev.c2":"À partir du bloc","tech.rev.c3":"Changement","tech.rev.c4":"Statut","tech.rev.2":"La transaction de récompense peut payer plusieurs adresses. Les pools reposent là-dessus.","tech.rev.3":"Des frais minimaux par octet remplacent les frais fixes, et un montant minimal s’applique.","tech.rev.4":"Le champ de difficulté peut contenir des valeurs de n’importe quelle taille.","tech.rev.5":"Des règles plus strictes pour les horodatages, l’encodage des blocs et la transaction de récompense.","tech.rev.6":"Comptes partagés, verrous temporels et de hash, paiements groupés, un nouvel arbre d’état et des limites plus élevées.","tech.rev.note":"Les révisions 2 à 5 ont corrigé et resserré des règles. La révision 6 est la première à ajouter des capacités, et la première que les anciens nœuds ne peuvent pas suivre.","tech.v6.h":"Révision 6","tech.v6.p":"Le prochain changement de règles commence au bloc 10 000. La communauté a choisi cette hauteur lors d’un vote le 25 octobre 2026. Il modifie l’enregistrement de compte, le format d’adresse et le format de transaction, pour que les comptes puissent faire plus que détenir un solde.","tech.v6.count":"Bloc 10 000","tech.v6.spec":"Lire la spécification de la révision 6","tech.v6.1.h":"Comptes partagés","tech.v6.1.p":"Des comptes qui exigent plusieurs signatures pour dépenser, par exemple 2 sur 3, avec jusqu’à 16 clés. Pour des fonds partagés et une épargne plus sûre.","tech.v6.2.h":"Verrous temporels","tech.v6.2.p":"Des YSR qui ne peuvent être dépensés qu’à partir d’une hauteur de bloc choisie.","tech.v6.3.h":"Verrous de hash","tech.v6.3.p":"Un paiement n’est débloqué qu’en échange d’un secret, et revient à l’expéditeur après une hauteur fixée. Deux parties peuvent échanger sans se faire confiance.","tech.v6.4.h":"Paiements groupés","tech.v6.4.p":"Une seule transaction paie jusqu’à 1 000 destinataires à la fois.","tech.v6.5.h":"Plus de place par bloc","tech.v6.5.p":"Jusqu’à 5 000 transactions par bloc au lieu de 2 000, et le bloc d’un pool peut payer jusqu’à 255 adresses au lieu de 64.","tech.v6.6.h":"Une base pour la suite","tech.v6.6.p":"Un arbre d’état conçu pour plusieurs milliers de comptes, des adresses avec une version et un identifiant de fork dans chaque signature.","tech.v6.same.h":"Ce qui ne change pas","tech.v6.same.1":"21 millions de YSR et le calendrier des halvings","tech.v6.same.2":"Des blocs de 10 minutes, SHA-256 et les règles de difficulté","tech.v6.same.3":"Chaque adresse, chaque clé et chaque solde","tech.v6.do.h":"Ce que tu dois faire","tech.v6.do.1":"Mettre à jour ton portefeuille et ton nœud avant le bloc 10 000","tech.v6.do.2":"Les mineurs, les mineurs GPU et le paquet HiveOS n’ont pas besoin de mise à jour","tech.v6.do.3":"Un portefeuille obsolète reçoit toujours des YSR. Il ne peut pas envoyer tant qu’il n’est pas mis à jour","tech.lim.h":"Limites connues","tech.lim.p":"Ce contre quoi le système ne protège pas aujourd’hui. La liste provient du document de sécurité du projet lui-même.","tech.lim.link":"Le modèle de sécurité complet","tech.lim.1.h":"Un petit réseau","tech.lim.1.p":"Le réseau compte deux nœuds d’amorçage, tous deux gérés par le même opérateur. La preuve de travail ne protège une chaîne que tant qu’aucune partie ne contrôle la majeure partie de la puissance de hachage, et la puissance de hachage qui mine via un pool est dirigée par l’opérateur de ce pool.","tech.lim.2.h":"Pas de points de contrôle","tech.lim.2.p":"Un nœud bascule vers toute chaîne valide ayant plus de travail, aussi loin en arrière qu’elle bifurque. Considère un transfert comme d’autant plus définitif que des blocs s’empilent au-dessus de lui.","tech.lim.3.h":"La source de données de l’explorateur","tech.lim.3.p":"L’explorateur et les apps lisent un miroir, une copie de la chaîne en base de données conservée pour la rapidité. C’est une commodité, pas l’autorité : la chaîne, c’est ce sur quoi les nœuds complets s’accordent.","tech.lim.4.h":"Places de pool","tech.lim.4.p":"Un pool compte au plus 64 places, 63 s’il prélève des frais ; à partir de la révision 6, ce sera 255 et 254. Ouvrir une session ne demande qu’une adresse valide, les places peuvent donc être occupées à peu de frais.","tech.lim.5.h":"Interfaces ouvertes","tech.lim.5.p":"L’interface HTTP d’un nœud ne limite pas les requêtes par client. Sur un nœud public, c’est à un reverse proxy de le faire.","tech.docs.1":"La spécification du protocole : formats, hachage, difficulté, règles de validité et vecteurs de test.","tech.docs.3":"Ce que la cryptographie et le consensus imposent, ce à quoi tu dois faire confiance, et les limites connues.","miner.title":"Cherche toi-même un nonce","miner.state":"S’exécute dans ton navigateur","miner.intro":"Ton navigateur prend l’en-tête du dernier bloc et essaie des nonces face à une cible plus facile. La vraie cible est bien au-delà de ce qu’un navigateur peut atteindre.","miner.bits":"Bits à zéro par lesquels le hash doit commencer","miner.odds":"{b} bits : environ 1 hash sur {n}","miner.start":"Lancer la recherche","miner.stop":"Arrêter","miner.attempts":"Tentatives","miner.speed":"Vitesse","miner.time":"Temps","miner.nonce":"Nonce trouvé","miner.hash":"Dernier hash essayé","miner.hashFound":"Hash trouvé","miner.target":"Cible de cette démo","miner.found":"Trouvé après {n} tentatives.","miner.none":"Aucun hash sous la cible en {n} tentatives. Recommence, ou demande moins de bits à zéro.","miner.stopped":"Arrêté après {n} tentatives.","miner.real":"À {r}, ce navigateur aurait besoin en moyenne d’environ {t} pour trouver un vrai bloc à la difficulté d’aujourd’hui.","field.version":"Version","field.version.d":"La version de l’en-tête. Elle vaut 1 aujourd’hui et passera à 6 avec la révision du consensus 6.","field.height":"Hauteur","field.height.d":"Le numéro de ce bloc, compté à partir du bloc 0.","field.prev":"Hash précédent","field.prev.d":"Le hash du bloc précédent. Il enchaîne les blocs : modifier un ancien bloc changerait tous les hashs qui le suivent.","field.merkle":"Racine des transactions","field.merkle.d":"Un seul hash sur toutes les transactions du bloc. Un seul octet modifié dans l’une d’elles le change.","field.state":"Racine d’état","field.state.d":"Un seul hash sur chaque solde et chaque nonce après ce bloc. Chaque nœud le calcule lui-même et compare.","field.time":"Horodatage","field.time.d":"Le moment où le mineur a construit le bloc. Il doit être postérieur à la médiane des 11 derniers blocs.","field.diff":"Difficulté","field.diff.d":"À quel point ce bloc devait être difficile. La cible en découle : 2^240 divisé par la difficulté.","field.count":"Nombre de transactions","field.count.d":"Combien de transactions le bloc contient, y compris celle qui paie la récompense.","field.extra":"Extranonce","field.extra.d":"Une valeur que le nœud donne à chaque mineur, pour que deux mineurs ne cherchent jamais sur les mêmes en-têtes.","field.nonce":"Nonce","field.nonce.d":"Le nombre que le mineur a fait varier jusqu’à ce que le hash passe sous la cible. Rien d’autre ne change entre deux tentatives.","proof.fixedBlock":"Fixé dans la chaîne","proof.block":"Bloc {h}","proof.found":"trouvé {ago}","proof.fixed":"Inchangé depuis le 9 sept. 2026","proof.cap":"L’en-tête du bloc : 136 octets en dix champs.","proof.bytesLabel":"Les 136 octets de l’en-tête du bloc {h}, en hexadécimal","proof.range":"octets {a} à {b}","proof.first":"SHA-256 des 136 octets","proof.hash":"SHA-256, appliqué deux fois : le hash du bloc","proof.target":"Cible à la difficulté {d}","proof.valid":"Valide. Le hash est sous la cible.","proof.invalid":"Non valide. Le hash est au-dessus de la cible.","proof.time":"Calculé dans ton navigateur en {ms} ms.","proof.again":"Vérifier à nouveau","proof.genesis":"Vérifier le bloc 0","proof.latest":"Vérifier le dernier bloc","proof.open":"Ouvrir ce bloc dans l’explorateur","check.1":"Structure","check.2":"Preuve de travail","check.3":"Place dans la chaîne","check.4":"Horodatage","check.5":"Difficulté","check.6":"Chaque transaction","check.7":"Racine d’état","chart.asTable":"Afficher les valeurs sous forme de tableau","chart.total":"total","chart.height":"Jusqu’au bloc","n.2000":"2 000","n.4000":"4 000","n.6000":"6 000","n.7000":"7 000","n.10000":"10 000","rev.active":"active depuis le {date}","rev.set":"fixée, encore {n} blocs","ms.done":"active","home.how.1.h":"Les mineurs cherchent","home.how.1.p":"Téléphones, PC et cartes graphiques hachent un en-tête de bloc encore et encore, chaque fois avec un nonce différent. Un hash sous la cible rend le bloc valide.","home.how.2.h":"Les nœuds vérifient","home.how.2.p":"Chaque nœud complet recalcule le travail, les signatures et tous les soldes, à partir du bloc 0. Un bloc qui enfreint une règle est rejeté, peu importe qui l’a envoyé.","home.how.3.h":"Le bloc paie","home.how.3.p":"C’est le bloc lui-même qui paie la récompense : à celui qui l’a trouvé seul, ou répartie entre les mineurs d’un pool, directement sur leurs adresses. Un pool ne détient jamais les pièces de qui que ce soit.","dev.api.down":"La requête a échoué ({why}). L’API ne répond pas d’ici pour le moment."};window.YSKAR_TEXTE_DA&&window.YSKAR_TEXTE_DA("fr");
